{"command":"cat > flags.go <<'GO'
package main

import (
	"fmt"
	"sort"
	"strconv"
	"strings"
)

type config struct {
	version          bool
	input            string
	inputSet         bool
	output           string
	outputSet        bool
	outputOverwrite  bool
	domain           string
	excludeSelectors []*selectorGroup
	includeSelectors []*selectorGroup
	strongDelimiter  string

	tablePadding       string
	tableHeaderPromote bool
	tableNewline       string
	tablePresentation  bool
	tableSkipEmpty     bool
	tableSpan          string

	pluginStrikethrough bool
	pluginTable         bool
}

func (c *config) requiresPluginError() string {
	if c.pluginTable {
		return ""
	}
	// The order in which missing-plugin options are reported is fixed
	// (determined by probing the original CLI).
	type entry struct {
		name string
		set  bool
	}
	entries := []entry{
		{"--opt-table-skip-empty-rows", c.tableSkipEmpty},
		{"--opt-table-span-cell-behavior", c.tableSpan != ""},
		{"--opt-table-header-promotion", c.tableHeaderPromote},
		{"--opt-table-newline-behavior", c.tableNewline != ""},
		{"--opt-table-presentation-tables", c.tablePresentation},
		{"--opt-table-cell-padding-behavior", c.tablePadding != ""},
	}
	for _, e := range entries {
		if e.set {
			return e.name + " requires --plugin-table to be enabled"
		}
	}
	return ""
}

type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindInput
	kindOutput
	kindSelectorExclude
	kindSelectorInclude
)

type flagDef struct {
	name string
	kind flagKind
}

var flagDefs = []flagDef{
	{"v", kindBool},
	{"version", kindBool},
	{"input", kindInput},
	{"output", kindOutput},
	{"output-overwrite", kindBool},
	{"domain", kindString},
	{"exclude-selector", kindSelectorExclude},
	{"include-selector", kindSelectorInclude},
	{"opt-strong-delimiter", kindString},
	{"opt-table-cell-padding-behavior", kindString},
	{"opt-table-header-promotion", kindBool},
	{"opt-table-newline-behavior", kindString},
	{"opt-table-presentation-tables", kindBool},
	{"opt-table-skip-empty-rows", kindBool},
	{"opt-table-span-cell-behavior", kindString},
	{"plugin-strikethrough", kindBool},
	{"plugin-table", kindBool},
}

var flagByName = func() map[string]flagDef {
	m := make(map[string]flagDef, len(flagDefs))
	for _, d := range flagDefs {
		m[d.name] = d
	}
	return m
}()

// parseFlags mimics the flag parsing behaviour of the original CLI
// (which is based on Go's standard flag package, with nicer errors
// for unknown flags).
func parseFlags(argv []string) (*config, []string, error) {
	cfg := &config{}
	args := argv
	for len(args) > 0 {
		s := args[0]
		if len(s) < 2 || s[0] != '-' {
			break
		}
		numMinuses := 1
		if s[1] == '-' {
			numMinuses++
			if len(s) == 2 { // "--" terminates the flags
				args = args[1:]
				break
			}
		}
		name := s[numMinuses:]
		if len(name) == 0 || name[0] == '-' || name[0] == '=' {
			return nil, nil, fmt.Errorf("bad flag syntax: %s", s)
		}
		// Determine if there is a value after '='.
		value := ""
		hasValue := false
		for i := 0; i < len(name); i++ {
			if name[i] == '=' {
				value = name[i+1:]
				hasValue = true
				name = name[:i]
				break
			}
		}
		// -h and -help are special: they show the help and stop parsing.
		if name == "help" || name == "h" {
			return nil, nil, errShowHelp
		}
		def, ok := flagByName[name]
		if !ok {
			return nil, nil, unknownFlagError(name)
		}
		args = args[1:]
		if def.kind == kindBool {
			if hasValue {
				b, err := parseBoolValue(value)
				if err != nil {
					return nil, nil, fmt.Errorf("invalid boolean value %q for -%s: parse error", value, name)
				}
				cfg.setBool(def.name, b)
			} else {
				cfg.setBool(def.name, true)
			}
			continue
		}
		// All other flags need a value.
		if !hasValue {
			if len(args) == 0 {
				return nil, nil, fmt.Errorf("flag needs an argument: -%s", name)
			}
			value = args[0]
			args = args[1:]
		}
		if err := cfg.setValue(def, name, value); err != nil {
			return nil, nil, err
		}
	}
	return cfg, args, nil
}

func parseBoolValue(s string) (bool, error) {
	switch s {
	case "1", "t", "T", "true", "TRUE", "True":
		return true, nil
	case "0", "f", "F", "false", "FALSE", "False":
		return false, nil
	}
	// Keep strconv import used and consistent; the error text above is fixed.
	_, err := strconv.ParseBool(s)
	return false, err
}

func (c *config) setBool(name string, b bool) {
	switch name {
	case "v", "version":
		c.version = b
	case "output-overwrite":
		c.outputOverwrite = b
	case "opt-table-header-promotion":
		c.tableHeaderPromote = b
	case "opt-table-presentation-tables":
		c.tablePresentation = b
	case "opt-table-skip-empty-rows":
		c.tableSkipEmpty = b
	case "plugin-strikethrough":
		c.pluginStrikethrough = b
	case "plugin-table":
		c.pluginTable = b
	}
}

func (c *config) setValue(def flagDef, name, value string) error {
	switch def.kind {
	case kindString:
		switch def.name {
		case "domain":
			c.domain = value
		case "opt-strong-delimiter":
			c.strongDelimiter = value
		case "opt-table-cell-padding-behavior":
			c.tablePadding = value
		case "opt-table-newline-behavior":
			c.tableNewline = value
		case "opt-table-span-cell-behavior":
			c.tableSpan = value
		}
		return nil
	case kindInput, kindOutput:
		trimmed := strings.TrimSpace(value)
		if trimmed == "" {
			return fmt.Errorf("invalid value %q for flag -%s: empty string", value, name)
		}
		if def.kind == kindInput {
			if c.inputSet {
				return fmt.Errorf("invalid value %q for flag -%s: another value has already been set", value, name)
			}
			c.input, c.inputSet = trimmed, true
		} else {
			if c.outputSet {
				return fmt.Errorf("invalid value %q for flag -%s: another value has already been set", value, name)
			}
			c.output, c.outputSet = trimmed, true
		}
		return nil
	case kindSelectorExclude, kindSelectorInclude:
		group, err := compileSelector(value)
		if err != nil {
			return fmt.Errorf("invalid value %q for flag -%s: invalid css selector: %s", value, name, err)
		}
		if def.kind == kindSelectorExclude {
			c.excludeSelectors = append(c.excludeSelectors, group)
		} else {
			c.includeSelectors = append(c.includeSelectors, group)
		}
		return nil
	}
	return nil
}

func unknownFlagError(name string) error {
	dash := "--"
	if len([]rune(name)) == 1 {
		dash = "-"
	}
	msg := fmt.Sprintf("unknown flag: %s%s", dash, name)
	if suggestion := suggestFlag(name); suggestion != "" {
		msg += fmt.Sprintf("\n\nDid you mean %s instead?", suggestion)
	}
	return fmt.Errorf("%s", msg)
}

func suggestFlag(typed string) string {
	names := make([]string, 0, len(flagDefs))
	for _, d := range flagDefs {
		names = append(names, d.name)
	}
	sort.Strings(names)
	best := ""
	bestDist := int(^uint(0) >> 1)
	for _, candidate := range names {
		d := levenshtein(typed, candidate)
		if d < bestDist {
			bestDist = d
			best = candidate
		}
	}
	if best == "" {
		return ""
	}
	if bestDist <= 4 && bestDist < len([]rune(typed)) {
		if len([]rune(best)) == 1 {
			return "-" + best
		}
		return "--" + best
	}
	return ""
}

func levenshtein(a, b string) int {
	ar := []rune(a)
	br := []rune(b)
	if len(ar) == 0 {
		return len(br)
	}
	if len(br) == 0 {
		return len(ar)
	}
	prev := make([]int, len(br)+1)
	cur := make([]int, len(br)+1)
	for j := 0; j <= len(br); j++ {
		prev[j] = j
	}
	for i := 1; i <= len(ar); i++ {
		cur[0] = i
		for j := 1; j <= len(br); j++ {
			cost := 0
			if ar[i-1] != br[j-1] {
				cost = 1
			}
			cur[j] = min3(prev[j]+1, cur[j-1]+1, prev[j-1]+cost)
		}
		copy(prev, cur)
	}
	return prev[len(br)]
}

func min3(a, b, c int) int {
	m := a
	if b < m {
		m = b
	}
	if c < m {
		m = c
	}
	return m
}
GO
gofmt -w flags.go"}

