package main

import (
	"fmt"
	"strconv"
	"strings"

	"golang.org/x/net/html"
)

// This file implements a CSS selector engine with behaviour (including
// error messages) modelled on what the original CLI exposes.

type selectorGroup struct {
	selectors []*complexSelector
	raw       string
}

type complexSelector struct {
	compounds   []*compoundSelector
	combinators []byte // combinators[i] connects compounds[i] -> compounds[i+1]
}

type compoundSelector struct {
	tag     string // "" = none, "*" = universal
	id      string
	hasID   bool
	classes []string
	attrs   []*attrSelector
	pseudos []*pseudoSelector
}

type attrSelector struct {
	key   string
	op    string // "", "=", "~=", "|=", "^=", "$=", "*=", "!="
	val   string
	csens bool // case-insensitive flag set
}

type pseudoSelector struct {
	name string
	a    int // nth: a
	b    int // nth: b
	arg  string
	sub  *selectorGroup
}

func compileSelector(input string) (*selectorGroup, error) {
	trimmed := strings.TrimSpace(input)
	if trimmed == "" {
		return nil, fmt.Errorf("empty string")
	}
	p := &selParser{s: trimmed}
	group, err := p.parseGroup()
	if err != nil {
		return nil, err
	}
	p.skipSpaces()
	if p.i < len(p.s) {
		return nil, fmt.Errorf("parsing %q: %d bytes left over", trimmed, len(p.s)-p.i)
	}
	group.raw = trimmed
	return group, nil
}

type selParser struct {
	s string
	i int
}

func (p *selParser) eof() bool { return p.i >= len(p.s) }

func (p *selParser) peek() byte {
	if p.eof() {
		return 0
	}
	return p.s[p.i]
}

func (p *selParser) skipSpaces() bool {
	start := p.i
	for !p.eof() {
		c := p.s[p.i]
		if c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' {
			p.i++
		} else {
			break
		}
	}
	return p.i > start
}

func (p *selParser) found() string {
	if p.eof() {
		return "EOF"
	}
	// Return the current character as-is.
	r := []rune(p.s[p.i:])
	if len(r) == 0 {
		return "EOF"
	}
	return string(r[0])
}

// parseGroup parses a comma-separated group of complex selectors.
func (p *selParser) parseGroup() (*selectorGroup, error) {
	group := &selectorGroup{}
	for {
		sel, err := p.parseComplex()
		if err != nil {
			return nil, err
		}
		group.selectors = append(group.selectors, sel)
		p.skipSpaces()
		if p.peek() == ',' {
			p.i++
			continue
		}
		break
	}
	return group, nil
}

func (p *selParser) parseComplex() (*complexSelector, error) {
	cs := &complexSelector{}
	comp, err := p.parseCompound()
	if err != nil {
		return nil, err
	}
	cs.compounds = append(cs.compounds, comp)
	for {
		hadSpace := p.skipSpaces()
		if p.eof() || p.peek() == ',' || p.peek() == ')' {
			break
		}
		c := p.peek()
		var comb byte
		if c == '>' || c == '+' || c == '~' {
			comb = c
			p.i++
			p.skipSpaces()
			if p.eof() || p.peek() == ',' || p.peek() == ')' {
				return nil, fmt.Errorf("expected selector, found %s instead", p.found())
			}
		} else if hadSpace {
			comb = ' '
		} else {
			break
		}
		next, err := p.parseCompound()
		if err != nil {
			return nil, err
		}
		cs.combinators = append(cs.combinators, comb)
		cs.compounds = append(cs.compounds, next)
	}
	return cs, nil
}

func isNameStart(c byte) bool {
	return c == '_' || c == '-' || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c >= 0x80
}

func isNameChar(c byte) bool {
	return isNameStart(c) || (c >= '0' && c <= '9')
}

// parseIdentifier reads a CSS identifier (roughly cascadia's rule).
func (p *selParser) parseIdentifier() string {
	start := p.i
	if !p.eof() && p.s[p.i] == '-' {
		p.i++
	}
	if p.eof() || !(p.s[p.i] == '_' || (p.s[p.i] >= 'a' && p.s[p.i] <= 'z') || (p.s[p.i] >= 'A' && p.s[p.i] <= 'Z') || p.s[p.i] >= 0x80) {
		p.i = start
		return ""
	}
	for !p.eof() && isNameChar(p.s[p.i]) {
		p.i++
	}
	return p.s[start:p.i]
}

// parseName reads a CSS name (digits allowed at the start).
func (p *selParser) parseName() string {
	start := p.i
	for !p.eof() && isNameChar(p.s[p.i]) {
		p.i++
	}
	return p.s[start:p.i]
}

func (p *selParser) parseCompound() (*compoundSelector, error) {
	comp := &compoundSelector{}
	c := p.peek()
	if c == '*' {
		p.i++
		comp.tag = "*"
	} else if !p.eof() && isNameStart(c) {
		ident := p.parseIdentifier()
		if ident == "" {
			return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
		}
		comp.tag = strings.ToLower(ident)
	} else if c == '.' || c == '#' || c == '[' || c == ':' {
		// no type selector
	} else {
		return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
	}
	for !p.eof() {
		switch p.peek() {
		case '.':
			p.i++
			ident := p.parseIdentifier()
			if ident == "" {
				return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
			}
			comp.classes = append(comp.classes, ident)
		case '#':
			p.i++
			name := p.parseName()
			if name == "" {
				return nil, fmt.Errorf("expected name, found %s instead", p.found())
			}
			comp.id = name
			comp.hasID = true
		case '[':
			attr, err := p.parseAttr()
			if err != nil {
				return nil, err
			}
			comp.attrs = append(comp.attrs, attr)
		case ':':
			pseudo, err := p.parsePseudo()
			if err != nil {
				return nil, err
			}
			comp.pseudos = append(comp.pseudos, pseudo)
		default:
			return comp, nil
		}
	}
	return comp, nil
}

func (p *selParser) parseAttr() (*attrSelector, error) {
	// current char is '['
	p.i++
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	key := p.parseIdentifier()
	if key == "" {
		return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
	}
	attr := &attrSelector{key: strings.ToLower(key)}
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	if p.peek() == ']' {
		p.i++
		return attr, nil
	}
	// Operator.
	if p.i+1 < len(p.s) {
		two := p.s[p.i : p.i+2]
		if two == "~=" || two == "|=" || two == "^=" || two == "$=" || two == "*=" || two == "!=" {
			attr.op = two
			p.i += 2
		}
	}
	if attr.op == "" {
		if p.peek() == '=' {
			attr.op = "="
			p.i++
		} else {
			return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
		}
	}
	p.skipSpaces()
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	// Value: quoted string or identifier.
	if q := p.peek(); q == '"' || q == '\'' {
		p.i++
		var sb strings.Builder
		closed := false
		for !p.eof() {
			ch := p.s[p.i]
			if ch == '\\' && p.i+1 < len(p.s) {
				p.i++
				sb.WriteByte(p.s[p.i])
				p.i++
				continue
			}
			if ch == q {
				p.i++
				closed = true
				break
			}
			sb.WriteByte(ch)
			p.i++
		}
		if !closed {
			return nil, fmt.Errorf("unexpected EOF in attribute selector")
		}
		attr.val = sb.String()
	} else {
		val := p.parseName()
		if val == "" {
			// Allow values that parseIdentifier accepts (e.g. starting with -).
			val = p.parseIdentifier()
		}
		if val == "" {
			return nil, fmt.Errorf("expected identifier, found %s instead", p.found())
		}
		attr.val = val
	}
	p.skipSpaces()
	// Optional case-sensitivity modifier.
	if !p.eof() && (p.peek() == 'i' || p.peek() == 'I' || p.peek() == 's' || p.peek() == 'S') {
		save := p.i
		_ = p.parseIdentifier()
		// Only treat as modifier if followed by space or ']'.
		if p.eof() || p.peek() == ']' || p.peek() == ' ' || p.peek() == '\t' {
			if p.s[save] == 'i' || p.s[save] == 'I' {
				attr.csens = true
			}
			p.skipSpaces()
		} else {
			p.i = save
		}
	}
	if p.eof() {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	if p.peek() != ']' {
		return nil, fmt.Errorf("unexpected EOF in attribute selector")
	}
	p.i++
	return attr, nil
}

var functionalPseudos = map[string]bool{
	"nth-child": true, "nth-last-child": true, "nth-of-type": true, "nth-last-of-type": true,
	"not": true, "has": true, "matches": true, "contains": true, "containsown": true, "lang": true,
}

var simplePseudos = map[string]bool{
	"root": true, "empty": true, "first-child": true, "last-child": true, "only-child": true,
	"first-of-type": true, "last-of-type": true, "only-of-type": true,
	"checked": true, "disabled": true, "enabled": true, "link": true, "visited": true,
	"target": true, "input": true, "hover": true, "focus": true, "active": true,
}

func (p *selParser) parsePseudo() (*pseudoSelector, error) {
	// current char is ':'
	p.i++
	if !p.eof() && p.peek() == ':' {
		// Pseudo-element.
		p.i++
		name := p.parseIdentifier()
		return nil, fmt.Errorf("pseudo-element %s found, but pseudo-elements support is disabled", name)
	}
	rawName := p.parseIdentifier()
	if rawName == "" {
		return nil, fmt.Errorf("got empty pseudoclass (or pseudoelement)")
	}
	name := strings.ToLower(rawName)
	ps := &pseudoSelector{name: name}
	if functionalPseudos[name] {
		if p.eof() || p.peek() != '(' {
			return nil, fmt.Errorf("unknown pseudoclass or pseudoelement :%s", rawName)
		}
		p.i++ // consume '('
		switch name {
		case "nth-child", "nth-last-child", "nth-of-type", "nth-last-of-type":
			a, b, err := p.parseNth()
			if err != nil {
				return nil, err
			}
			ps.a, ps.b = a, b
		case "not", "has", "matches":
			inner, err := p.parseParenSelectorGroup()
			if err != nil {
				return nil, err
			}
			ps.sub = inner
		case "contains", "containsown":
			arg, err := p.parseContainsArg()
			if err != nil {
				return nil, err
			}
			ps.arg = arg
		case "lang":
			arg, err := p.parseLangArg()
			if err != nil {
				return nil, err
			}
			ps.arg = arg
		}
		return ps, nil
	}
	if simplePseudos[name] {
		return ps, nil
	}
	return nil, fmt.Errorf("unknown pseudoclass or pseudoelement :%s", rawName)
}

// parseParenSelectorGroup parses a selector group up to the matching ')'.
func (p *selParser) parseParenSelectorGroup() (*selectorGroup, error) {
	// Extract text up to the matching close paren (respecting nesting,
	// brackets and quotes).
	start := p.i
	depth := 1
	i := p.i
	var quote byte
	for i < len(p.s) {
		c := p.s[i]
		if quote != 0 {
			if c == '\\' {
				i += 2
				continue
			}
			if c == quote {
				quote = 0
			}
			i++
			continue
		}
		switch c {
		case '"', '\'':
			quote = c
		case '(':
			depth++
		case ')':
			depth--
			if depth == 0 {
				inner := p.s[start:i]
				sub, err := compileSelector(inner)
				if err != nil {
					return nil, err
				}
				p.i = i + 1
				return sub, nil
			}
		}
		i++
	}
	return nil, fmt.Errorf("expected ')' but didn't find it")
}

func (p *selParser) parseContainsArg() (string, error) {
	p.skipSpaces()
	if p.eof() {
		return "", fmt.Errorf("expected ')' but didn't find it")
	}
	if p.peek() == ')' {
		return "", fmt.Errorf("expected identifier, found %s instead", p.found())
	}
	var arg string
	if q := p.peek(); q == '"' || q == '\'' {
		p.i++
		var sb strings.Builder
		closed := false
		for !p.eof() {
			c := p.s[p.i]
			if c == '\\' && p.i+1 < len(p.s) {
				p.i++
				sb.WriteByte(p.s[p.i])
				p.i++
				continue
			}
			if c == q {
				p.i++
				closed = true
				break
			}
			sb.WriteByte(c)
			p.i++
		}
		if !closed {
			return "", fmt.Errorf("expected ')' but didn't find it")
		}
		arg = sb.String()
	} else {
		start := p.i
		for !p.eof() && p.peek() != ')' {
			p.i++
		}
		arg = strings.TrimSpace(p.s[start:p.i])
		if arg == "" {
			return "", fmt.Errorf("expected identifier, found %s instead", p.found())
		}
	}
	p.skipSpaces()
	if p.eof() || p.peek() != ')' {
		return "", fmt.Errorf("expected ')' but didn't find it")
	}
	p.i++
	return arg, nil
}

func (p *selParser) parseLangArg() (string, error) {
	start := p.i
	for !p.eof() && p.peek() != ')' {
		p.i++
	}
	if p.eof() {
		return "", fmt.Errorf("expected ')' but didn't find it")
	}
	arg := strings.TrimSpace(p.s[start:p.i])
	p.i++ // consume ')'
	return arg, nil
}

func (p *selParser) parseNth() (int, int, error) {
	// p is positioned after '('.
	start := p.i
	for !p.eof() && p.peek() != ')' {
		p.i++
	}
	if p.eof() {
		return 0, 0, fmt.Errorf("expected ')' but didn't find it")
	}
	rawArg := p.s[start:p.i]
	p.i++ // consume ')'
	arg := strings.Join(strings.Fields(strings.ToLower(rawArg)), "")
	switch arg {
	case "odd":
		return 2, 1, nil
	case "even":
		return 2, 0, nil
	}
	if n, err := strconv.Atoi(arg); err == nil {
		return 0, n, nil
	}
	// Parse an+b.
	idx := 0
	readInt := func() (int, bool) {
		j := idx
		if j < len(arg) && (arg[j] == '+' || arg[j] == '-') {
			j++
		}
		digits := 0
		for j < len(arg) && arg[j] >= '0' && arg[j] <= '9' {
			j++
			digits++
		}
		if digits == 0 {
			return 0, false
		}
		n, err := strconv.Atoi(arg[idx:j])
		if err != nil {
			return 0, false
		}
		idx = j
		return n, true
	}
	a := 0
	// Optional sign for a.
	sign := 1
	if idx < len(arg) && (arg[idx] == '+' || arg[idx] == '-') {
		if arg[idx] == '-' {
			sign = -1
		}
		idx++
		if idx >= len(arg) {
			return 0, 0, fmt.Errorf("unexpected character while attempting to parse expression of form an+b")
		}
	}
	if idx < len(arg) && arg[idx] == 'n' {
		a = sign
		idx++
	} else {
		// Coefficient digits then 'n'.
		save := idx
		if n, ok := readInt(); ok {
			if idx < len(arg) && arg[idx] == 'n' {
				a = n
				idx++
			} else {
				_ = save
				return 0, 0, fmt.Errorf("expected ')' but didn't find it")
			}
		} else {
			return 0, 0, fmt.Errorf("unexpected character while attempting to parse expression of form an+b")
		}
	}
	b := 0
	if idx < len(arg) {
		if arg[idx] != '+' && arg[idx] != '-' {
			return 0, 0, fmt.Errorf("expected ')' but didn't find it")
		}
		n, ok := readInt()
		if !ok {
			return 0, 0, fmt.Errorf("expected ')' but didn't find it")
		}
		b = n
	}
	if idx != len(arg) {
		return 0, 0, fmt.Errorf("expected ')' but didn't find it")
	}
	return a, b, nil
}

// ---------- matching ----------

func (g *selectorGroup) matches(n *html.Node) bool {
	if g == nil {
		return false
	}
	for _, sel := range g.selectors {
		if sel.matches(n, nil) {
			return true
		}
	}
	return false
}

func (cs *complexSelector) matches(n *html.Node, limit *html.Node) bool {
	if n == nil || n.Type != html.ElementNode {
		return false
	}
	return cs.matchAt(len(cs.compounds)-1, n, limit)
}

func (cs *complexSelector) matchAt(idx int, n *html.Node, limit *html.Node) bool {
	if n == nil || n.Type != html.ElementNode {
		return false
	}
	if !cs.compounds[idx].matches(n, limit) {
		return false
	}
	if idx == 0 {
		return true
	}
	comb := cs.combinators[idx-1]
	switch comb {
	case '>':
		return cs.matchAt(idx-1, parentElement(n), limit)
	case ' ':
		for anc := parentElement(n); anc != nil; anc = parentElement(anc) {
			if cs.matchAt(idx-1, anc, limit) {
				return true
			}
			if anc == limit {
				break
			}
		}
		return false
	case '+':
		return cs.matchAt(idx-1, prevElementSibling(n), limit)
	case '~':
		for sib := prevElementSibling(n); sib != nil; sib = prevElementSibling(sib) {
			if cs.matchAt(idx-1, sib, limit) {
				return true
			}
		}
		return false
	}
	return false
}

func (c *compoundSelector) matches(n *html.Node, limit *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	if c.tag != "" && c.tag != "*" {
		if !strings.EqualFold(n.Data, c.tag) {
			return false
		}
	}
	if c.hasID {
		id, ok := getAttr(n, "id")
		if !ok || id != c.id {
			return false
		}
	}
	for _, cls := range c.classes {
		classAttr, _ := getAttr(n, "class")
		found := false
		for _, f := range strings.Fields(classAttr) {
			if f == cls {
				found = true
				break
			}
		}
		if !found {
			return false
		}
	}
	for _, a := range c.attrs {
		if !a.matches(n) {
			return false
		}
	}
	for _, ps := range c.pseudos {
		if !ps.matches(n, limit) {
			return false
		}
	}
	return true
}

func (a *attrSelector) matches(n *html.Node) bool {
	val, ok := getAttr(n, a.key)
	if a.op == "" {
		return ok
	}
	if a.op == "!=" {
		if !ok {
			return true
		}
		if a.csens {
			return !strings.EqualFold(val, a.val)
		}
		return val != a.val
	}
	if !ok {
		return false
	}
	v, target := val, a.val
	if a.csens {
		v, target = strings.ToLower(v), strings.ToLower(target)
	}
	switch a.op {
	case "=":
		return v == target
	case "~=":
		for _, f := range strings.Fields(v) {
			if f == target {
				return true
			}
		}
		return false
	case "|=":
		return v == target || strings.HasPrefix(v, target+"-")
	case "^=":
		if target == "" {
			return false
		}
		return strings.HasPrefix(v, target)
	case "$=":
		if target == "" {
			return false
		}
		return strings.HasSuffix(v, target)
	case "*=":
		if target == "" {
			return false
		}
		return strings.Contains(v, target)
	}
	return false
}

func (ps *pseudoSelector) matches(n *html.Node, limit *html.Node) bool {
	switch ps.name {
	case "root":
		return n.Parent != nil && n.Parent.Type == html.DocumentNode
	case "empty":
		return n.FirstChild == nil
	case "first-child":
		return prevElementSibling(n) == nil
	case "last-child":
		return nextElementSibling(n) == nil
	case "only-child":
		return prevElementSibling(n) == nil && nextElementSibling(n) == nil
	case "first-of-type":
		for s := prevElementSibling(n); s != nil; s = prevElementSibling(s) {
			if strings.EqualFold(s.Data, n.Data) {
				return false
			}
		}
		return true
	case "last-of-type":
		for s := nextElementSibling(n); s != nil; s = nextElementSibling(s) {
			if strings.EqualFold(s.Data, n.Data) {
				return false
			}
		}
		return true
	case "only-of-type":
		for s := prevElementSibling(n); s != nil; s = prevElementSibling(s) {
			if strings.EqualFold(s.Data, n.Data) {
				return false
			}
		}
		for s := nextElementSibling(n); s != nil; s = nextElementSibling(s) {
			if strings.EqualFold(s.Data, n.Data) {
				return false
			}
		}
		return true
	case "nth-child":
		return nthMatches(ps.a, ps.b, elementIndex(n))
	case "nth-last-child":
		return nthMatches(ps.a, ps.b, elementIndexFromEnd(n))
	case "nth-of-type":
		return nthMatches(ps.a, ps.b, ofTypeIndex(n))
	case "nth-last-of-type":
		return nthMatches(ps.a, ps.b, ofTypeIndexFromEnd(n))
	case "not":
		return !ps.sub.matches(n)
	case "matches":
		return ps.sub.matches(n)
	case "has":
		found := false
		walkElements(n, func(desc *html.Node) {
			if desc == n {
				return
			}
			if found {
				return
			}
			for _, sel := range ps.sub.selectors {
				if sel.matches(desc, n) {
					found = true
					return
				}
			}
		})
		return found
	case "contains":
		return strings.Contains(textContent(n), ps.arg)
	case "containsown":
		var sb strings.Builder
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			if c.Type == html.TextNode {
				sb.WriteString(c.Data)
			}
		}
		return strings.Contains(sb.String(), ps.arg)
	case "lang":
		return matchLang(n, ps.arg)
	case "link":
		switch strings.ToLower(n.Data) {
		case "a", "area", "link":
			_, ok := getAttr(n, "href")
			return ok
		}
		return false
	case "visited", "target", "hover", "focus", "active":
		return false
	case "checked":
		switch strings.ToLower(n.Data) {
		case "input":
			_, ok := getAttr(n, "checked")
			return ok
		case "option":
			_, ok := getAttr(n, "selected")
			return ok
		}
		return false
	case "disabled":
		return matchDisabled(n)
	case "enabled":
		return matchEnabled(n)
	case "input":
		switch strings.ToLower(n.Data) {
		case "input", "select", "textarea", "button":
			return true
		}
		return false
	}
	return false
}

func matchLang(n *html.Node, arg string) bool {
	for node := n; node != nil; node = node.Parent {
		if node.Type == html.ElementNode {
			if lang, ok := getAttr(node, "lang"); ok {
				// This mirrors the observed behaviour of the selector
				// engine used by the original: it checks whether the
				// inherited language starts with "<arg>-".
				if strings.HasPrefix(strings.ToLower(lang), strings.ToLower(arg)+"-") {
					return true
				}
				return false
			}
		}
	}
	return false
}

var formTags = map[string]bool{
	"button": true, "input": true, "select": true, "textarea": true,
	"optgroup": true, "option": true, "fieldset": true, "keygen": true,
}

func matchDisabled(n *html.Node) bool {
	if !formTags[strings.ToLower(n.Data)] {
		return false
	}
	_, ok := getAttr(n, "disabled")
	return ok
}

func matchEnabled(n *html.Node) bool {
	if formTags[strings.ToLower(n.Data)] {
		return !matchDisabled(n)
	}
	switch strings.ToLower(n.Data) {
	case "a", "area", "link":
		_, ok := getAttr(n, "href")
		return ok
	}
	return false
}

func nthMatches(a, b, idx int) bool {
	if idx <= 0 {
		return false
	}
	if a == 0 {
		return idx == b
	}
	diff := idx - b
	if a > 0 {
		return diff >= 0 && diff%a == 0
	}
	return diff <= 0 && diff%a == 0
}

func elementIndex(n *html.Node) int {
	idx := 1
	for s := prevElementSibling(n); s != nil; s = prevElementSibling(s) {
		idx++
	}
	return idx
}

func elementIndexFromEnd(n *html.Node) int {
	idx := 1
	for s := nextElementSibling(n); s != nil; s = nextElementSibling(s) {
		idx++
	}
	return idx
}

func ofTypeIndex(n *html.Node) int {
	idx := 1
	for s := prevElementSibling(n); s != nil; s = prevElementSibling(s) {
		if strings.EqualFold(s.Data, n.Data) {
			idx++
		}
	}
	return idx
}

func ofTypeIndexFromEnd(n *html.Node) int {
	idx := 1
	for s := nextElementSibling(n); s != nil; s = nextElementSibling(s) {
		if strings.EqualFold(s.Data, n.Data) {
			idx++
		}
	}
	return idx
}

func parentElement(n *html.Node) *html.Node {
	if n == nil || n.Parent == nil {
		return nil
	}
	if n.Parent.Type == html.ElementNode {
		return n.Parent
	}
	return nil
}

func prevElementSibling(n *html.Node) *html.Node {
	for s := n.PrevSibling; s != nil; s = s.PrevSibling {
		if s.Type == html.ElementNode {
			return s
		}
	}
	return nil
}

func nextElementSibling(n *html.Node) *html.Node {
	for s := n.NextSibling; s != nil; s = s.NextSibling {
		if s.Type == html.ElementNode {
			return s
		}
	}
	return nil
}

func walkElements(root *html.Node, fn func(*html.Node)) {
	if root.Type == html.ElementNode {
		fn(root)
	}
	for c := root.FirstChild; c != nil; c = c.NextSibling {
		walkElements(c, fn)
	}
}

func textContent(n *html.Node) string {
	var sb strings.Builder
	var walk func(*html.Node)
	walk = func(node *html.Node) {
		if node.Type == html.TextNode {
			sb.WriteString(node.Data)
		}
		for c := node.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(n)
	return sb.String()
}

func getAttr(n *html.Node, key string) (string, bool) {
	for _, a := range n.Attr {
		if strings.EqualFold(a.Key, key) {
			return a.Val, true
		}
	}
	return "", false
}

// queryAll returns matching elements in document order.
func queryAll(root *html.Node, groups []*selectorGroup) []*html.Node {
	var out []*html.Node
	var walk func(*html.Node)
	walk = func(n *html.Node) {
		if n.Type == html.ElementNode {
			for _, g := range groups {
				if g.matches(n) {
					out = append(out, n)
					break
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			walk(c)
		}
	}
	walk(root)
	return out
}
