package main

import (
	"strings"
	"unicode"
)

// Whitespace collapsing: runs of space, tab, LF and CR become a single
// ASCII space. Other characters (including NBSP and unicode spaces)
// are preserved.
func collapseWhitespace(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	inRun := false
	for _, r := range s {
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' {
			if !inRun {
				b.WriteByte(' ')
				inRun = true
			}
			continue
		}
		inRun = false
		b.WriteRune(r)
	}
	return b.String()
}

func isSpaceRune(r rune) bool {
	return unicode.IsSpace(r)
}

type escapeContext struct {
	inBlockquote bool
	inHeading    bool
	inTableCell  bool
	strikethrough bool
}

type lineState int

const (
	lineNone lineState = iota
	lineBlockStart
	lineAfterBreak
)

// escapeText applies the "smart" escaping rules to a text node whose
// whitespace has already been collapsed.
func escapeText(s string, ctx escapeContext, state lineState) string {
	if s == "" {
		return ""
	}
	runes := []rune(s)

	// Determine the position of the first non-space rune, which is where
	// line-start patterns are anchored.
	firstNonSpace := -1
	for i, r := range runes {
		if !isSpaceRune(r) {
			firstNonSpace = i
			break
		}
	}

	forceEscape := map[int]bool{}
	suppress := map[int]bool{}

	if state != lineNone && !ctx.inBlockquote && !ctx.inHeading && firstNonSpace >= 0 {
		applyLinePatterns(runes, firstNonSpace, state, forceEscape, suppress)
	}

	var b strings.Builder
	for i, r := range runes {
		switch r {
		case '\\':
			b.WriteString("\\\\")
			continue
		case '<':
			b.WriteString("&lt;")
			continue
		case '>':
			b.WriteString("&gt;")
			continue
		}
		escape := forceEscape[i]
		if !escape && !suppress[i] {
			switch r {
			case '`':
				escape = true
			case '*', '_':
				if i+1 < len(runes) && !isSpaceRune(runes[i+1]) {
					escape = true
				}
			case '~':
				if ctx.strikethrough && i+1 < len(runes) && !isSpaceRune(runes[i+1]) {
					escape = true
				}
			case '[':
				// Escape when a closing bracket appears later in the text.
				for j := i + 1; j < len(runes); j++ {
					if runes[j] == ']' {
						escape = true
						break
					}
				}
			case '|':
				if ctx.inTableCell {
					escape = true
				}
			}
		}
		if escape {
			b.WriteByte('\\')
		}
		b.WriteRune(r)
	}
	return b.String()
}

func applyLinePatterns(runes []rune, start int, state lineState, forceEscape, suppress map[int]bool) {
	t := runes[start:]
	if len(t) == 0 {
		return
	}
	// Fenced code block with tildes at the start of a line: escape only
	// the first tilde and leave the rest of the initial run alone.
	if len(t) >= 3 && t[0] == '~' && t[1] == '~' && t[2] == '~' {
		forceEscape[start] = true
		for i := start + 1; i < len(runes) && runes[i] == '~'; i++ {
			suppress[i] = true
		}
	}

	// ATX heading: 1-6 '#' followed by space or end of line.
	if t[0] == '#' {
		n := 0
		for n < len(t) && t[n] == '#' {
			n++
		}
		if n <= 6 && (n == len(t) || t[n] == ' ') {
			forceEscape[start] = true
		}
	}

	// Ordered list markers: digits followed by '.' or ')' and then a
	// space (or the end of the text).
	{
		i := 0
		for i < len(t) && t[i] >= '0' && t[i] <= '9' {
			i++
		}
		if i > 0 && i < len(t) && (t[i] == '.' || t[i] == ')') {
			if i+1 == len(t) || t[i+1] == ' ' {
				forceEscape[start+i] = true
			}
		}
	}

	if state == lineAfterBreak {
		// Setext headings / thematic breaks following a paragraph line.
		if t[0] == '-' {
			forceEscape[start] = true
		}
		if t[0] == '=' {
			forceEscape[start] = true
		}
	}

	// Unordered list markers and related start-of-line constructs.
	switch t[0] {
	case '-':
		if len(t) == 1 || t[1] == ' ' {
			forceEscape[start] = true
		} else if allOfKind(t, '-', 3) {
			forceEscape[start] = true
		}
	case '+':
		if len(t) == 1 || t[1] == ' ' {
			forceEscape[start] = true
		}
	case '*':
		if len(t) == 1 || t[1] == ' ' {
			forceEscape[start] = true
		} else if allOfKind(t, '*', 3) {
			forceEscape[start] = true
		}
	case '_':
		if allOfKind(t, '_', 3) {
			forceEscape[start] = true
		}
	}
}

// allOfKind reports whether the text consists solely of the given
// character and spaces, with at least min occurrences of the character.
func allOfKind(t []rune, kind rune, min int) bool {
	count := 0
	for _, r := range t {
		if r == kind {
			count++
		} else if r != ' ' {
			return false
		}
	}
	return count >= min
}
