import (
	"net/url"
	"strings"
)

// parseDomainBase implements the lenient parsing the original CLI
// applies to the --domain value. It returns nil when the domain cannot
// be used as a base URL.
func parseDomainBase(domain string) *url.URL {
	if domain == "" {
		return nil
	}
	u, err := url.Parse(domain)
	if err == nil && u.Host != "" {
		return u
	}
	u2, err2 := url.Parse("http://" + domain)
	if err2 == nil && u2.Host != "" {
		return u2
	}
	return nil
}

// resolveHref makes href absolute (when a domain is configured) and
// then escapes it so it can be placed inside a markdown link/image.
func resolveHref(rawHref string, base *url.URL) string {
	href := strings.TrimSpace(rawHref)
	ref, err := url.Parse(href)
	var final string
	if err != nil {
		final = href
		return escapeRawURL(final)
	}
	if base != nil {
		final = base.ResolveReference(ref).String()
	} else {
		final = ref.String()
		if final == "" {
			final = href
		}
	}
	return escapeParsedURL(final)
}

const hexDigits = "0123456789ABCDEF"

func pctEncodeByte(b byte) string {
	return "%" + string(hexDigits[b>>4]) + string(hexDigits[b&0x0F])
}

func isHexDigit(c byte) bool {
	return (c >= '0' && c <= '9') || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F')
}

func isAllowedByte(c byte, allowed string) bool {
	return strings.IndexByte(allowed, c) >= 0
}

const unreserved = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~"

// encodeComponent escapes bytes of s that are not allowed, preserving
// existing %XX escape sequences.
func encodeComponent(s string, allowed string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		if c == '%' && i+2 < len(s) && isHexDigit(s[i+1]) && isHexDigit(s[i+2]) {
			b.WriteString(s[i : i+3])
			i += 2
			continue
		}
		if c < 0x80 && isAllowedByte(c, allowed) {
			b.WriteByte(c)
			continue
		}
		b.WriteString(pctEncodeByte(c))
	}
	return b.String()
}

// escapeRawURL is used when the href cannot be parsed at all: only the
// characters that would break a markdown link destination are escaped.
func escapeRawURL(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch c {
		case ' ', '\t', '\n', '\r', '"', '(', ')', '<', '>', '[', ']':
			b.WriteString(pctEncodeByte(c))
		default:
			if c >= 0x80 || c < 0x20 {
				b.WriteString(pctEncodeByte(c))
			} else {
				b.WriteByte(c)
			}
		}
	}
	return b.String()
}

type urlParts struct {
	scheme       string
	hasScheme    bool
	authority    string
	hasAuthority bool
	path         string // path when not opaque
	opaque       string
	hasOpaque    bool
	query        string
	hasQuery     bool
	fragment     string
	hasFragment  bool
}

func splitURL(s string) urlParts {
	var p urlParts
	rest := s
	if idx := strings.Index(rest, "#"); idx >= 0 {
		p.fragment = rest[idx+1:]
		p.hasFragment = true
		rest = rest[:idx]
	}
	if idx := strings.Index(rest, "?"); idx >= 0 {
		p.query = rest[idx+1:]
		p.hasQuery = true
		rest = rest[:idx]
	}
	// Scheme.
	if colon := strings.Index(rest, ":"); colon > 0 {
		candidate := rest[:colon]
		valid := true
		for i := 0; i < len(candidate); i++ {
			c := candidate[i]
			if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9' || c == '+' || c == '-' || c == '.') {
				valid = false
				break
			}
		}
		if valid && len(candidate) > 0 {
			first := candidate[0]
			if first >= 'a' && first <= 'z' || first >= 'A' && first <= 'Z' {
				p.scheme = candidate
				p.hasScheme = true
				rest = rest[colon+1:]
			}
		}
	}
	if strings.HasPrefix(rest, "//") {
		p.hasAuthority = true
		rest = rest[2:]
		if slash := strings.Index(rest, "/"); slash >= 0 {
			p.authority = rest[:slash]
			rest = rest[slash:]
		} else {
			p.authority = rest
			rest = ""
		}
		p.path = rest
		return p
	}
	if p.hasScheme {
		p.opaque = rest
		p.hasOpaque = true
		return p
	}
	p.path = rest
	return p
}

const (
	pathAllowed     = unreserved + "!$&'*+,;:=@/"
	fragmentAllowed = unreserved + "!$&'*+,;:=@/?"
	opaqueAllowed   = unreserved + "!$&'*+,-./:;=?@\\^_`{|}"
	userinfoAllowed = unreserved + "!$&'*+,;:"
	hostAllowed     = unreserved + "!$&'*+,;=:."
)

func escapeParsedURL(s string) string {
	p := splitURL(s)
	var b strings.Builder
	if p.hasScheme {
		b.WriteString(p.scheme)
		b.WriteByte(':')
	}
	if p.hasAuthority {
		b.WriteString("//")
		b.WriteString(escapeAuthority(p.authority))
		b.WriteString(encodeComponent(p.path, pathAllowed))
	} else if p.hasOpaque {
		b.WriteString(encodeComponent(p.opaque, opaqueAllowed))
	} else {
		b.WriteString(encodeComponent(p.path, pathAllowed))
	}
	if p.hasQuery {
		b.WriteByte('?')
		b.WriteString(encodeQuery(p.query))
	}
	if p.hasFragment {
		b.WriteByte('#')
		b.WriteString(encodeComponent(p.fragment, fragmentAllowed))
	}
	return b.String()
}

func escapeAuthority(auth string) string {
	userinfo := ""
	hostport := auth
	hasUserinfo := false
	if at := strings.LastIndex(auth, "@"); at >= 0 {
		userinfo = auth[:at]
		hostport = auth[at+1:]
		hasUserinfo = true
	}
	var b strings.Builder
	if hasUserinfo {
		b.WriteString(encodeComponent(userinfo, userinfoAllowed))
		b.WriteByte('@')
	}
	b.WriteString(encodeComponent(hostport, hostAllowed))
	return b.String()
}

func encodeQuery(query string) string {
	if query == "" {
		return ""
	}
	parts := strings.Split(query, "&")
	for i, part := range parts {
		if eq := strings.Index(part, "="); eq >= 0 {
			parts[i] = encodeQueryComponent(part[:eq]) + "=" + encodeQueryComponent(part[eq+1:])
		} else {
			parts[i] = encodeQueryComponent(part)
		}
	}
