type converter struct {
	cfg      *config
	base     *url.URL
	absorbed map[*html.Node]*absorbedInfo
}

type absorbedInfo struct {
	close       string
	outer       string
	shouldClose bool
}

type rctx struct {
	inBlockquote    bool
	inHeading       bool
	inTableCell     bool
	structuralTable bool
	cellPreserve    bool
}

func newConverter(cfg *config) *converter {
	return &converter{
		cfg:      cfg,
		base:     parseDomainBase(cfg.domain),
		absorbed: map[*html.Node]*absorbedInfo{},
	}
}

func (c *converter) strongDelim() string {
	if c.cfg.strongDelimiter == "" {
		return "**"
	}
	return c.cfg.strongDelimiter
}

// validateOptions performs the per-conversion validation that happens
// after input has been read (plugin initialisation first, then the
// strong-delimiter check).
func (c *converter) validateOptions() error {
	if c.cfg.pluginTable {
		// Order of checks: span, newline, cell padding.
		if v := c.cfg.tableSpan; v != "" && v != "empty" && v != "mirror" {
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for span cell behavior", v)
		}
		if v := c.cfg.tableNewline; v != "" && v != "skip" && v != "preserve" {
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for newline behavior", v)
		}
		if v := c.cfg.tablePadding; v != "" && v != "aligned" && v != "minimal" && v != "none" {
			return fmt.Errorf("error while initializing \"table\" plugin: unknown value %q for cell padding behavior", v)
		}
	}
	if v := c.cfg.strongDelimiter; v != "" {
		if strings.Count(v, "*") != 2 && strings.Count(v, "_") != 2 {
			return fmt.Errorf("invalid value for --opt-strong-delimiter=%q must be exactly 2 characters of \"**\" or \"__\"", v)
		}
	}
	return nil
}

func (c *converter) convert(content []byte) (string, error) {
	if err := c.validateOptions(); err != nil {
		return "", err
	}
	c.absorbed = map[*html.Node]*absorbedInfo{}
	doc, err := html.Parse(bytes.NewReader(content))
	if err != nil {
		return "", err
	}
	root := doc
	if len(c.cfg.includeSelectors) > 0 {
		matches := queryAll(root, c.cfg.includeSelectors)
		newDoc := &html.Node{Type: html.DocumentNode}
		body := &html.Node{Type: html.ElementNode, Data: "body"}
		newDoc.AppendChild(body)
		for _, m := range matches {
			detach(m)
			body.AppendChild(m)
		}
		root = newDoc
	}
	if len(c.cfg.excludeSelectors) > 0 {
		matches := queryAll(root, c.cfg.excludeSelectors)
		for _, m := range matches {
			detach(m)
		}
	}
	out := c.renderNode(root, rctx{})
	return strings.TrimSpace(out), nil
}

func detach(n *html.Node) {
	if n.Parent != nil {
		n.Parent.RemoveChild(n)
	}
}

func tagName(n *html.Node) string {
	if n.Type != html.ElementNode {
		return ""
	}
	return strings.ToLower(n.Data)
}

func childNodes(n *html.Node) []*html.Node {
	var out []*html.Node
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		out = append(out, ch)
	}
	return out
}

var ignoredTags = map[string]bool{
	"script": true, "style": true, "noscript": true, "iframe": true,
	"textarea": true, "input": true, "head": true,
}

var blockTags = map[string]bool{
	"address": true, "article": true, "aside": true, "blockquote": true,
	"dd": true, "details": true, "dialog": true, "div": true, "dl": true,
	"dt": true, "fieldset": true, "figcaption": true, "figure": true,
	"footer": true, "form": true, "h1": true, "h2": true, "h3": true,
	"h4": true, "h5": true, "h6": true, "header": true, "hgroup": true,
	"hr": true, "li": true, "main": true, "nav": true, "ol": true,
	"p": true, "pre": true, "section": true, "table": true, "ul": true,
}

func isBlockNode(n *html.Node, ctx rctx) bool {
	if n.Type != html.ElementNode {
		return false
	}
	tag := tagName(n)
	if ignoredTags[tag] {
		return false
	}
	if blockTags[tag] {
		return true
	}
	if ctx.structuralTable && (tag == "caption" || tag == "tr") {
		return true
	}
	return false
}

// ---------- inline builder ----------

type inlineBuilder struct {
	buf        string
	state      lineState
	barrier    bool
	afterBlock bool
}

func hasContent(s string) bool {
	return strings.Trim(s, " \t\n\r") != ""
}

func (b *inlineBuilder) ensureBlockSep(s string) {
	if !b.afterBlock {
		return
	}
	if !hasContent(s) {
		return
	}
	b.afterBlock = false
	if strings.TrimSpace(b.buf) == "" {
		return
	}
	if !strings.HasSuffix(b.buf, "\n\n") {
		if strings.HasSuffix(b.buf, "\n") {
			b.buf += "\n"
		} else {
			b.buf += "\n\n"
		}
	}
}

func (b *inlineBuilder) noteWritten(s string) {
	if idx := strings.LastIndex(s, "\n"); idx >= 0 {
		rest := s[idx+1:]
		if !hasContent(rest) {
			b.state = lineAfterBreak
		} else {
			b.state = lineNone
		}
		return
	}
	if hasContent(s) {
		b.state = lineNone
	}
}

func (b *inlineBuilder) Text(s string) {
	if s == "" {
		return
	}
	b.ensureBlockSep(s)
	orig := s
	if !b.barrier && strings.HasSuffix(b.buf, " ") && strings.HasPrefix(s, " ") {
		s = s[1:]
		if s == "" {
			return
		}
	}
	_ = orig
	b.buf += s
	b.noteWritten(s)
	b.barrier = false
}

func (b *inlineBuilder) Raw(s string) {
	if s == "" {
		return
	}
	b.ensureBlockSep(s)
	b.buf += s
	b.noteWritten(s)
	b.barrier = false
}

func (b *inlineBuilder) Barrier() {
	b.barrier = true
}

func (b *inlineBuilder) WriteBlockChunk(chunk string) {
	if strings.TrimSpace(chunk) == "" {
		return
	}
	if strings.TrimSpace(b.buf) != "" && !b.afterBlock {
		if !strings.HasSuffix(b.buf, "\n\n") {
			if strings.HasSuffix(b.buf, "\n") {
				b.buf += "\n"
			} else {
				b.buf += "\n\n"
			}
		}
	}
	b.buf += chunk
	b.afterBlock = true
	b.state = lineBlockStart
	b.barrier = false
}

func (b *inlineBuilder) writeBr() {
	if strings.HasSuffix(b.buf, "\n") {
		b.Raw("\n")
	} else {
		b.Raw("  \n")
	}
}

// ---------- sequence rendering ----------

type seqChunk struct {
	text      string
	fromBlock bool
	tag       string
}

func (ch *seqChunk) isList() bool { return ch.tag == "ul" || ch.tag == "ol" }

func (c *converter) renderSequence(nodes []*html.Node, ctx rctx) string {
	var chunks []*seqChunk
	ib := &inlineBuilder{state: lineBlockStart}
	flush := func() {
		s := strings.TrimSpace(ib.buf)
		if s != "" {
			chunks = append(chunks, &seqChunk{text: s})
		}
		ib = &inlineBuilder{state: lineBlockStart}
	}
	for _, n := range nodes {
		if isBlockNode(n, ctx) {
			flush()
			text := c.renderNode(n, ctx)
			if strings.TrimSpace(text) != "" {
				chunks = append(chunks, &seqChunk{text: text, fromBlock: true, tag: tagName(n)})
			}
		} else {
			c.renderInline(n, ib, ctx)
		}
	}
	flush()

	var sb strings.Builder
	wrote := 0
	for i, ch := range chunks {
		if i > 0 {
			// Insert the list separator marker between adjacent lists.
			var parts []string
			_ = parts
			sep := "\n\n"
			if ctx.cellPreserve && chunks[i-1].fromBlock && ch.fromBlock {
				sep = "\n\n\n\n"
			}
			if chunks[i-1].isList() && ch.isList() {
				sb.WriteString(sep)
				sb.WriteString("<!--THE END-->")
				sb.WriteString(sep)
			} else {
				sb.WriteString(sep)
			}
		}
		sb.WriteString(ch.text)
		wrote++
	}
	_ = wrote
	return sb.String()
}

// ---------- node rendering ----------

func (c *converter) renderNode(n *html.Node, ctx rctx) string {
	switch n.Type {
	case html.DocumentNode:
		return c.renderSequence(childNodes(n), ctx)
	case html.TextNode:
		ib := &inlineBuilder{state: lineBlockStart}
		c.renderInline(n, ib, ctx)
		return strings.TrimSpace(ib.buf)
	case html.ElementNode:
		tag := tagName(n)
		if ignoredTags[tag] {
			return ""
		}
		switch tag {
		case "html", "body":
			return c.renderSequence(childNodes(n), ctx)
		case "h1", "h2", "h3", "h4", "h5", "h6":
			return c.renderHeading(n, ctx, int(tag[1]-'0'))
		case "blockquote":
			return c.renderBlockquote(n, ctx)
		case "pre":
			return c.renderPre(n)
		case "hr":
			return "* * *"
		case "ul", "ol":
			return c.renderList(n, ctx)
		case "table":
			return c.renderTable(n, ctx)
		}
		return c.renderSequence(childNodes(n), ctx)
	default:
		return ""
	}
}

func (c *converter) escapeCtx(ctx rctx) escapeContext {
	return escapeContext{
		inBlockquote:  ctx.inBlockquote,
		inHeading:     ctx.inHeading,
		inTableCell:   ctx.inTableCell,
		strikethrough: c.cfg.pluginStrikethrough,
	}
}

func (c *converter) renderInline(n *html.Node, ib *inlineBuilder, ctx rctx) {
	switch n.Type {
	case html.TextNode:
		ib.Text(escapeText(collapseWhitespace(n.Data), c.escapeCtx(ctx), ib.state))
		return
	case html.ElementNode:
		// handled below
	default:
		return
	}
	tag := tagName(n)
	if ignoredTags[tag] {
		return
	}
	switch tag {
	case "br":
		ib.writeBr()
		return
	case "wbr", "area", "embed", "param", "track":
		ib.Barrier()
		return
	case "strong", "b", "em", "i":
		c.renderFormat(n, ib, ctx)
		return
	case "del", "s", "strike":
		if c.cfg.pluginStrikethrough {
			c.renderFormat(n, ib, ctx)
		} else {
			for _, ch := range childNodes(n) {
				c.renderInline(ch, ib, ctx)
			}
		}
		return
	case "code", "kbd", "samp", "tt", "var":
		c.renderCode(n, ib, ctx)
		return
	case "a":
		c.renderLink(n, ib, ctx)
		return
	case "img":
		c.renderImage(n, ib, ctx)
		return
	}
	if isBlockNode(n, ctx) {
		ib.WriteBlockChunk(c.renderNode(n, ctx))
		return
	}
	for _, ch := range childNodes(n) {
		c.renderInline(ch, ib, ctx)
	}
}

// ---------- format (strong/em/strikethrough/code) ----------

type formatFamily int

const (
	familyNone formatFamily = iota
	familyEmphasis
	familyStrike
	familyCode
)

func familyOf(n *html.Node, strikethrough bool) formatFamily {
	if n.Type != html.ElementNode {
		return familyNone
	}
	switch tagName(n) {
	case "strong", "b", "em", "i":
		return familyEmphasis
	case "del", "s", "strike":
		if strikethrough {
			return familyStrike
		}
	case "code", "kbd", "samp", "tt", "var":
		return familyCode
	}
	return familyNone
}

func (c *converter) formatMarker(n *html.Node) (string, formatFamily) {
	switch tagName(n) {
	case "strong", "b":
		return c.strongDelim(), familyEmphasis
	case "em", "i":
		return "*", familyEmphasis
	case "del", "s", "strike":
		return "~~", familyStrike
	}
	return "", familyNone
}

// findFormatRun finds following siblings that belong to the same format
// family and should be merged with this node. It also descends into
// following <span> elements.
func (c *converter) findFormatRun(n *html.Node, family formatFamily) []*html.Node {
	if n.Parent == nil {
		return nil
	}
	siblings := childNodes(n.Parent)
	idx := -1
	for i, s := range siblings {
		if s == n {
			idx = i
			break
		}
	}
	if idx < 0 {
		return nil
	}
	var chain []*html.Node
	i := idx + 1
scan:
	for i < len(siblings) {
		sib := siblings[i]
		if sib.Type == html.CommentNode {
			i++
			continue
		}
		if familyOf(sib, c.cfg.pluginStrikethrough) == family && family != familyNone {
			chain = append(chain, sib)
			i++
			continue
		}
		if sib.Type == html.ElementNode && tagName(sib) == "span" {
			cand, complete := collectSpanRun(sib, family, c.cfg.pluginStrikethrough)
			chain = append(chain, cand...)
			if complete {
				i++
				continue
			}
			break scan
		}
		break scan
	}
	return chain
}

func collectSpanRun(span *html.Node, family formatFamily, strikethrough bool) ([]*html.Node, bool) {
	var cand []*html.Node
	for _, ch := range childNodes(span) {
		if ch.Type == html.CommentNode {
			continue
		}
		if familyOf(ch, strikethrough) == family && family != familyNone {
			cand = append(cand, ch)
			continue
		}
		if ch.Type == html.ElementNode && tagName(ch) == "span" {
			sub, complete := collectSpanRun(ch, family, strikethrough)
			cand = append(cand, sub...)
			if !complete {
				return cand, false
			}
			continue
		}
		return cand, false
	}
	return cand, true
}

func splitLeadTrail(s string) (string, string, string) {
	start := 0
	for start < len(s) {
		r, size := utf8.DecodeRuneInString(s[start:])
		if !unicode.IsSpace(r) {
			break
		}
		start += size
	}
	end := len(s)
	for end > start {
		r, size := utf8.DecodeLastRuneInString(s[:end])
		if !unicode.IsSpace(r) {
			break
		}
		end -= size
	}
	if start >= end {
		return s, "", ""
	}
	return s[:start], s[start:end], s[end:]
}

func wrapContentLines(core, firstOpen, outer, finalClose string) string {
	lines := strings.Split(core, "\n")
	first, last := -1, -1
	for i, line := range lines {
		if strings.TrimSpace(line) != "" {
			if first < 0 {
				first = i
			}
			last = i
		}
	}
	if first < 0 {
		return core
	}
	out := make([]string, len(lines))
	for i, line := range lines {
		trimmed := strings.TrimSpace(line)
		if trimmed == "" {
			continue
		}
		open := outer
		if i == first {
			open = firstOpen
		}
		closer := outer
		if i == last {
			closer = finalClose
		}
		out[i] = open + trimmed + closer
	}
	for i := 0; i+1 < len(out); i++ {
		if out[i] != "" && out[i+1] != "" {
			out[i] += "  "
		}
	}
	return strings.Join(out, "\n")
}

func (c *converter) renderFormat(n *html.Node, ib *inlineBuilder, ctx rctx) {
	marker, family := c.formatMarker(n)
	if info, ok := c.absorbed[n]; ok {
		c.renderFormatContent(n, ib, ctx, "", info.outer, info, family)
		return
	}
	chain := c.findFormatRun(n, family)
	finalClose := marker
	if len(chain) > 0 {
		for idx, cn := range chain {
			c.absorbed[cn] = &absorbedInfo{close: marker, outer: marker, shouldClose: idx == len(chain)-1}
		}
		finalClose = ""
	}
	c.renderFormatContent(n, ib, ctx, marker, marker, &absorbedInfo{close: finalClose, outer: marker, shouldClose: true}, family)
	_ = finalClose
}

// renderFormatContent renders a format element. info carries the
// closing behaviour: for a normal element close is its own marker,
// for an absorbed element the opening is suppressed.
func (c *converter) renderFormatContent(n *html.Node, ib *inlineBuilder, ctx rctx, firstOpen string, outer string, info *absorbedInfo, family formatFamily) {
	sub := &inlineBuilder{state: lineNone}
	for _, ch := range childNodes(n) {
		c.renderInline(ch, sub, ctx)
	}
	content := sub.buf
	if !hasContent(content) {
		if content != "" {
			ib.Text(content)
		}
		return
	}
	lead, core, trail := splitLeadTrail(content)
	if core == "" {
		ib.Text(content)
		return
	}
	finalClose := info.close
	if !info.shouldClose {
		finalClose = ""
	}
	// For a normal (non-absorbed) element, info.close is the marker to
	// use at the very end; renderFormat passes it appropriately.
	wrapped := wrapContentLines(core, firstOpen, outer, finalClose)
	if lead != "" && !strings.Contains(lead, "\n") {
		ib.Text(lead)
	}
	ib.Raw(wrapped)
	if trail != "" && !strings.Contains(trail, "\n") {
		ib.Text(trail)
	}
}

func (c *converter) renderCode(n *html.Node, ib *inlineBuilder, ctx rctx) {
	if info, ok := c.absorbed[n]; ok {
		content := codeText(n)
		if content == "" {
			return
		}
		if info.shouldClose {
			pad := ""
			if strings.HasSuffix(content, "`") {
				pad = " "
			}
			ib.Raw(content + pad + info.close)
		} else {
			ib.Raw(content)
		}
		return
	}
	chain := c.findFormatRun(n, familyCode)
	own := codeText(n)
	combined := own
	var chainContents []string
	for _, cn := range chain {
		ct := codeText(cn)
		chainContents = append(chainContents, ct)
		combined += ct
	}
	if combined == "" {
		return
	}
	delim := codeDelimiter(combined)
	if len(chain) > 0 {
		for idx, cn := range chain {
			c.absorbed[cn] = &absorbedInfo{close: delim, outer: delim, shouldClose: idx == len(chain)-1}
		}
		pad := ""
		if strings.HasPrefix(combined, "`") {
			pad = " "
		}
		ib.Raw(delim + pad + own)
		return
	}
	padStart, padEnd := "", ""
	if strings.HasPrefix(combined, "`") {
		padStart = " "
	}
	if strings.HasSuffix(combined, "`") {
		padEnd = " "
	}
	ib.Raw(delim + padStart + combined + padEnd + delim)
}

func codeDelimiter(content string) string {
	maxRun := 0
	run := 0
	for _, r := range content {
		if r == '`' {
			run++
			if run > maxRun {
				maxRun = run
			}
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", maxRun+1)
}

// codeText extracts the textual content of a code element, collapsing
// whitespace like normal inline text.
func codeText(n *html.Node) string {
	var sb strings.Builder
	var walk func(*html.Node)
	walk = func(node *html.Node) {
		if node.Type == html.TextNode {
			sb.WriteString(node.Data)
			return
		}
		if node.Type == html.ElementNode {
			tag := tagName(node)
			if ignoredTags[tag] {
				return
			}
			if tag == "br" {
				sb.WriteString("\n")
				return
			}
		}
		for ch := node.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		walk(ch)
	}
	return strings.TrimSpace(collapseWhitespace(sb.String()))
}

// rawText extracts the unmodified textual content below a node
// (used for <pre>).
func rawText(n *html.Node) string {
	var sb strings.Builder
	var walk func(*html.Node)
	walk = func(node *html.Node) {
		if node.Type == html.TextNode {
			sb.WriteString(node.Data)
			return
		}
		if node.Type == html.ElementNode {
			tag := tagName(node)
			if ignoredTags[tag] {
				return
			}
			if tag == "br" {
				sb.WriteString("\n")
				return
			}
		}
		for ch := node.FirstChild; ch != nil; ch = ch.NextSibling {
			walk(ch)
		}
	}
	for ch := n.FirstChild; ch != nil; ch = ch.NextSibling {
		walk(ch)
	}
	return sb.String()
}

// ---------- link / image ----------

func titlePart(titleRaw string, hasTitle bool) string {
	if !hasTitle || titleRaw == "" {
		return ""
	}
	title := strings.ReplaceAll(titleRaw, "\n", " ")
	if strings.Contains(title, "\"") && !strings.Contains(title, "'") {
		return " '" + title + "'"
	}
	return " \"" + strings.ReplaceAll(title, "\"", "\\\"") + "\""
}

func (c *converter) renderLink(n *html.Node, ib *inlineBuilder, ctx rctx) {
	hrefRaw, _ := getAttr(n, "href")
	titleRaw, hasTitle := getAttr(n, "title")
	dest := resolveHref(hrefRaw, c.base)

	sub := &inlineBuilder{state: lineNone}
	for _, ch := range childNodes(n) {
		c.renderInline(ch, sub, ctx)
	}
	content := sub.buf
	if !hasContent(content) {
		ib.Raw("[](" + dest + titlePart(titleRaw, hasTitle) + ")")
		return
	}
	lead, core, trail := splitLeadTrail(content)
	if core == "" {
		ib.Raw("[](" + dest + titlePart(titleRaw, hasTitle) + ")")
		return
	}
	if lead != "" && !strings.Contains(lead, "\n") {
		ib.Text(lead)
	}
	ib.Raw("[" + core + "](" + dest + titlePart(titleRaw, hasTitle) + ")")
	if trail != "" && !strings.Contains(trail, "\n") {
		ib.Text(trail)
	}
}

func (c *converter) renderImage(n *html.Node, ib *inlineBuilder, ctx rctx) {
	srcRaw, ok := getAttr(n, "src")
	if !ok || strings.TrimSpace(srcRaw) == "" {
		ib.Barrier()
		return
	}
	altRaw, _ := getAttr(n, "alt")
	alt := strings.ReplaceAll(altRaw, "\n", " ")
	alt = strings.ReplaceAll(alt, "[", "\\[")
	alt = strings.ReplaceAll(alt, "]", "\\]")
	titleRaw, hasTitle := getAttr(n, "title")
	dest := resolveHref(srcRaw, c.base)
	ib.Raw("![" + alt + "](" + dest + titlePart(titleRaw, hasTitle) + ")")
}

// ---------- heading / blockquote / pre ----------

func collapseASCIISpaces(s string) string {
	var b strings.Builder
	lastSpace := false
	for i := 0; i < len(s); i++ {
		if s[i] == ' ' {
			if lastSpace {
				continue
			}
			lastSpace = true
		} else {
			lastSpace = false
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func (c *converter) renderHeading(n *html.Node, ctx rctx, level int) string {
	subCtx := ctx
	subCtx.inHeading = true
	sub := &inlineBuilder{state: lineNone}
	for _, ch := range childNodes(n) {
		c.renderInline(ch, sub, subCtx)
	}
	content := strings.ReplaceAll(sub.buf, "\n", " ")
	content = collapseASCIISpaces(content)
	content = strings.TrimSpace(content)
	if content == "" {
		return ""
	}
	return strings.Repeat("#", level) + " " + content
}

func (c *converter) renderBlockquote(n *html.Node, ctx rctx) string {
	subCtx := ctx
	subCtx.inBlockquote = true
	inner := c.renderSequence(childNodes(n), subCtx)
	if strings.TrimSpace(inner) == "" {
		return ""
	}
	lines := strings.Split(inner, "\n")
	out := make([]string, len(lines))
	inFence := false
	justOpened := false
	fenceLen := 0
	for i, line := range lines {
		stripped := strings.TrimLeft(line, " \t")
		for strings.HasPrefix(stripped, "> ") {
			stripped = strings.TrimLeft(stripped[2:], " \t")
		}
		isFence, run := fenceInfo(stripped)
		if inFence {
			if isFence && run >= fenceLen && isFenceLine(stripped) {
				out[i] = "> " + line
				inFence = false
				justOpened = false
			} else if justOpened {
				out[i] = "> " + line
				justOpened = false
			} else {
				out[i] = line
			}
			continue
		}
		out[i] = "> " + line
		if isFence {
			inFence = true
			justOpened = true
			fenceLen = run
		}
	}
	return strings.Join(out, "\n")
}

// fenceInfo reports whether a line starts with a backtick fence and
// the length of the opening run.
func fenceInfo(line string) (bool, int) {
	if !strings.HasPrefix(line, "```") {
		return false, 0
	}
	n := 0
	for n < len(line) && line[n] == '`' {
		n++
	}
	return true, n
}

func isFenceLine(line string) bool {
	if line == "" {
		return false
	}
	for i := 0; i < len(line); i++ {
		if line[i] != '`' {
			return false
		}
	}
	return true
}

func (c *converter) renderPre(n *html.Node) string {
	content := rawText(n)
	lang := preLanguage(n)
	maxRun := 0
	run := 0
	for _, r := range content {
		if r == '`' {
			run++
			if run > maxRun {
				maxRun = run
			}
		} else {
			run = 0
		}
	}
	fenceLen := maxRun + 1
	if fenceLen < 3 {
		fenceLen = 3
	}
	fence := strings.Repeat("`", fenceLen)
	var sb strings.Builder
	sb.WriteString(fence)
	sb.WriteString(lang)
	sb.WriteString("\n")
	sb.WriteString(content)
	if !strings.HasSuffix(content, "\n") {
		sb.WriteString("\n")
	}
	sb.WriteString(fence)
	return sb.String()
}

func preLanguage(n *html.Node) string {
	var lang string
	var found bool
	var walk func(*html.Node)
	walk = func(node *html.Node) {
		if found {
			return
		}
		if node.Type == html.ElementNode && tagName(node) == "code" {
			classAttr, _ := getAttr(node, "class")
			for _, tok := range strings.Fields(classAttr) {
				if strings.HasPrefix(tok, "language-") {
					lang = tok[len("language-"):]
					found = true
					return
				}
				if strings.HasPrefix(tok, "lang-") {
					lang = tok[len("lang-"):]
					found = true
					return
				}
			}
			found = true
			return
		}
		for ch := node.FirstChild; ch != nil && !found; ch = ch.NextSibling {
			walk(ch)
		}
	}
	for ch := n.FirstChild; ch != nil && !found; ch = ch.NextSibling {
		walk(ch)
	}
	return lang
}

// parseSpan parses a colspan/rowspan attribute.
func parseSpan(n *html.Node, attr string) int {
	v, ok := getAttr(n, attr)
	if !ok {
		return 1
	}
	num, err := strconv.Atoi(v)
	if err != nil || num < 1 {
		return 1
	}
	if num > 1000 {
		return 1000
	}
	return num
}
