{"command":"cat > table.go <<'GO'
package main

import (
	"strings"
	"unicode/utf8"

	"golang.org/x/net/html"
)

var tableDenyTags = map[string]bool{
	"h1": true, "h2": true, "h3": true, "h4": true, "h5": true, "h6": true,
	"ul": true, "ol": true, "blockquote": true, "hr": true, "table": true,
}

type tableCell struct {
	node    *html.Node
	content string
	colspan int
	rowspan int
}

type tableRow struct {
	cells   []*tableCell
	inThead bool
}

func tableOpt(cfg *config) (padding, newline, span string) {
	padding = cfg.tablePadding
	if padding == "" {
		padding = "aligned"
	}
	newline = cfg.tableNewline
	if newline == "" {
		newline = "skip"
	}
	span = cfg.tableSpan
	if span == "" {
		span = "empty"
	}
	return
}

func (c *converter) renderTable(n *html.Node, ctx rctx) string {
	if !c.cfg.pluginTable {
		return c.renderSequence(childNodes(n), ctx)
	}
	_, newlineBehavior, _ := tableOpt(c.cfg)

	if role, ok := getAttr(n, "role"); ok && role == "presentation" && !c.cfg.tablePresentation {
		return c.renderFallbackTable(n, ctx)
	}

	// Tables containing certain block-level elements cannot be
	// converted and fall back to a plain rendering.
	deny := false
	var scan func(*html.Node)
	scan = func(node *html.Node) {
		for ch := node.FirstChild; ch != nil; ch = ch.NextSibling {
			if ch.Type == html.ElementNode && tableDenyTags[tagName(ch)] {
				deny = true
				return
			}
			scan(ch)
			if deny {
				return
			}
		}
	}
	scan(n)
	if deny {
		return c.renderFallbackTable(n, ctx)
	}

	rows := collectTableRows(n)
	caption := c.renderTableCaption(n, ctx)

	headerIdx := -1
	for i, r := range rows {
		if r.inThead {
			headerIdx = i
			break
		}
	}
	if headerIdx < 0 {
		for i, r := range rows {
			for _, cell := range r.cells {
				if tagName(cell.node) == "th" {
					headerIdx = i
					break
				}
			}
			if headerIdx >= 0 {
				break
			}
		}
	}
	if headerIdx < 0 && c.cfg.tableHeaderPromote && len(rows) > 0 {
		headerIdx = 0
	}

	// Display order: header row first, then the rest in order.
	var display []*tableRow
	if headerIdx >= 0 {
		display = append(display, rows[headerIdx])
		for i, r := range rows {
			if i != headerIdx {
				display = append(display, r)
			}
		}
	} else {
		display = rows
	}

	// Render all cell contents.
	cellCtx := ctx
	cellCtx.inTableCell = true
	cellCtx.structuralTable = false
	if newlineBehavior == "preserve" {
		cellCtx.cellPreserve = true
	}
	for _, r := range display {
		for _, cell := range r.cells {
			cell.content = c.renderSequence(childNodes(cell.node), cellCtx)
		}
	}

	if newlineBehavior == "skip" {
		for _, r := range display {
			for _, cell := range r.cells {
				if strings.Contains(cell.content, "\n") {
					return c.renderFallbackTable(n, ctx)
				}
			}
		}
	}

	// Expand spans into a grid.
	grid, origins := expandTableGrid(display, c.cfg)
	// grid[0] corresponds to the header when headerIdx >= 0.

	numCols := 0
	for _, row := range grid {
		if len(row) > numCols {
			numCols = len(row)
		}
	}
	if numCols == 0 {
		return caption
	}
	// Normalise row lengths.
	for i := range grid {
		for len(grid[i]) < numCols {
			grid[i] = append(grid[i], "")
			origins[i] = append(origins[i], nil)
		}
	}

	bodyStart := 0
	var headerContents []string
	var headerOrigins []*html.Node
	if headerIdx >= 0 {
		headerContents = grid[0]
		headerOrigins = origins[0]
		bodyStart = 1
	} else {
		headerContents = make([]string, numCols)
		headerOrigins = nil
	}
	bodyGrid := grid[bodyStart:]
	bodyOrigins := origins[bodyStart:]

	if headerIdx < 0 && len(bodyGrid) > 0 {
		headerOrigins = bodyOrigins[0]
	} else if headerIdx < 0 {
		headerOrigins = make([]*html.Node, numCols)
	}

	if c.cfg.tableSkipEmpty {
		var kept [][]string
		var keptOrigins [][]*html.Node
		for i, row := range bodyGrid {
			empty := true
			for _, cell := range row {
				if strings.TrimSpace(cell) != "" {
					empty = false
					break
				}
			}
			if !empty {
				kept = append(kept, row)
				keptOrigins = append(keptOrigins, bodyOrigins[i])
			}
		}
		bodyGrid = kept
		bodyOrigins = keptOrigins
	}
	_ = bodyOrigins

	// In preserve mode, convert newlines in cell contents to <br />.
	if newlineBehavior == "preserve" {
		headerContents = convertCellNewlines(headerContents)
		for i := range bodyGrid {
			bodyGrid[i] = convertCellNewlines(bodyGrid[i])
		}
	}

 aligns := make([]string, numCols)
	for col := 0; col < numCols; col++ {
		if col < len(headerOrigins) && headerOrigins[col] != nil {
			if v, ok := getAttr(headerOrigins[col], "align"); ok {
				if v == "left" || v == "center" || v == "right" {
					aligns[col] = v
				}
			}
		}
	}

	tableText := formatTable(headerContents, bodyGrid, aligns, c.cfg)
	if tableText == "" {
		return caption
	}
	if caption != "" {
		return tableText + "\n\n" + caption
	}
	return tableText
}

func (c *converter) renderTableCaption(n *html.Node, ctx rctx) string {
	var parts []string
	for _, ch := range childNodes(n) {
		if ch.Type == html.ElementNode && tagName(ch) == "caption" {
			capCtx := ctx
			capCtx.inTableCell = false
			capCtx.structuralTable = false
			content := c.renderSequence(childNodes(ch), capCtx)
			if strings.TrimSpace(content) != "" {
				parts = append(parts, strings.TrimSpace(content))
			}
		}
	}
	return strings.Join(parts, "\n\n")
}

func (c *converter) renderFallbackTable(n *html.Node, ctx rctx) string {
	sub := ctx
	sub.structuralTable = true
	sub.inTableCell = false
	return c.renderSequence(childNodes(n), sub)
}

func collectTableRows(table *html.Node) []*tableRow {
	var rows []*tableRow
	var process func(nodes []*html.Node, inThead bool)
	process = func(nodes []*html.Node, inThead bool) {
		for _, ch := range nodes {
			if ch.Type != html.ElementNode {
				continue
			}
			switch tagName(ch) {
			case "thead":
				process(childNodes(ch), true)
			case "tbody", "tfoot":
				process(childNodes(ch), false)
			case "tr":
				row := &tableRow{inThead: inThead}
				for _, cellNode := range childNodes(ch) {
					if cellNode.Type == html.ElementNode {
						tag := tagName(cellNode)
						if tag == "td" || tag == "th" {
							row.cells = append(row.cells, &tableCell{
								node:    cellNode,
								colspan: parseSpan(cellNode, "colspan"),
								rowspan: parseSpan(cellNode, "rowspan"),
							})
						}
					}
				}
				rows = append(rows, row)
			}
		}
	}
	process(childNodes(table), false)
	return rows
}

type pendingSpan struct {
	remaining int
	content   string
	origin    *html.Node
}

func expandTableGrid(display []*tableRow, cfg *config) ([][]string, [][]*html.Node) {
	_, _, spanBehavior := tableOpt(cfg)
	active := map[int]*pendingSpan{}
	var grid [][]string
	var origins [][]*html.Node
	for _, row := range display {
		slots := map[int]string{}
		orig := map[int]*html.Node{}
		col := 0
		placePending := func() {
			pend := active[col]
			if spanBehavior == "mirror" {
				slots[col] = pend.content
			} else {
				slots[col] = ""
			}
			orig[col] = pend.origin
			col++
		}
		for _, cell := range row.cells {
			// Fill any columns occupied by rowspans from above.
			for {
				if _, ok := active[col]; ok {
					placePending()
				} else {
					break
				}
			}
			startCol := col
			_ = startCol
			for k := 0; k < cell.colspan; k++ {
				if _, ok := active[col]; ok && k > 0 {
					placePending()
					k--
					continue
				}
				if k == 0 || spanBehavior == "mirror" {
					slots[col] = cell.content
				} else {
					slots[col] = ""
				}
				orig[col] = cell.node
				col++
			}
			// Register the rowspan for the columns this cell occupies.
			if cell.rowspan > 1 {
				// Determine the columns occupied by this cell.
				for cc := col - cell.colspan; cc < col; cc++ {
					if cc >= 0 {
						active[cc] = &pendingSpan{remaining: cell.rowspan, content: cell.content, origin: cell.node}
					}
				}
			}
		}
		// Place any remaining pending columns that are within reach.
		for {
			if _, ok := active[col]; ok {
				placePending()
			} else {
				break
			}
		}
		maxCol := -1
		for cc := range slots {
			if cc > maxCol {
				maxCol = cc
			}
		}
		rowSlots := make([]string, maxCol+1)
		rowOrigins := make([]*html.Node, maxCol+1)
		for cc := 0; cc <= maxCol; cc++ {
			if v, ok := slots[cc]; ok {
				rowSlots[cc] = v
				rowOrigins[cc] = orig[cc]
			}
		}
		grid = append(grid, rowSlots)
		origins = append(origins, rowOrigins)

		// Age the active spans: entries that were active during this
		// row lose one remaining row; freshly added entries start
		// counting from the next row.
		next := map[int]*pendingSpan{}
		for cc, pend := range active {
			if pend.remaining > 1 {
				next[cc] = &pendingSpan{remaining: pend.remaining - 1, content: pend.content, origin: pend.origin}
			}
		}
		active = next
	}
	return grid, origins
}

func convertCellNewlines(row []string) []string {
	out := make([]string, len(row))
	for i, cell := range row {
		out[i] = cellContentToBr(cell)
	}
	return out
}

// cellContentToBr replaces newlines with <br /> except for newlines
// that sit strictly inside a fenced code block.
func cellContentToBr(content string) string {
	if !strings.Contains(content, "\n") {
		return content
	}
	lines := strings.Split(content, "\n")
	var b strings.Builder
	inFence := false
	fenceLen := 0
	lineIsFence := make([]bool, len(lines))
	lineIsClosing := make([]bool, len(lines))
	for i, line := range lines {
		stripped := strings.TrimLeft(line, " \t")
		isF, run := fenceInfo(stripped)
		if !inFence {
			if isF {
				inFence = true
				fenceLen = run
				lineIsFence[i] = true
			}
		} else {
			if isF && run >= fenceLen && isFenceLine(stripped) {
				inFence = false
				lineIsFence[i] = true
				lineIsClosing[i] = true
			}
		}
	}
	_ = lineIsClosing
	inFence = false
	for i, line := range lines {
		if i > 0 {
			prevContent := inFence && !lineIsFence[i-1] && !lineIsFence[i]
			curContent := false
			// Recompute fence state before this line.
			curContent = prevContent && inFence
			_ = curContent
			if prevContent {
				b.WriteString("\n")
			} else {
				b.WriteString("<br />")
			}
		}
		b.WriteString(line)
		// Update fence state after writing the line.
		stripped := strings.TrimLeft(line, " \t")
		isF, run := fenceInfo(stripped)
		if !inFence {
			if isF {
				inFence = true
				fenceLen = run
			}
		} else {
			if isF && run >= fenceLen && isFenceLine(stripped) {
				inFence = false
			}
		}
	}
	return b.String()
}

func formatTable(header []string, body [][]string, aligns []string, cfg *config) string {
	padding, _, _ := tableOpt(cfg)
	numCols := len(header)
	if numCols == 0 {
		return ""
	}
	widths := make([]int, numCols)
	for col := 0; col < numCols; col++ {
		widths[col] = 1
	}
	measure := func(row []string) {
		for col := 0; col < numCols && col < len(row); col++ {
			if w := utf8.RuneCountInString(row[col]); w > widths[col] {
				widths[col] = w
			}
		}
	}
	measure(header)
	for _, row := range body {
