func (c *converter) renderTableCaption(n *html.Node, ctx rctx) string {
	var parts []string
	for _, ch := range childNodes(n) {
		if ch.Type == html.ElementNode && tagName(ch) == "caption" {
			capCtx := ctx
			capCtx.inTableCell = false
			capCtx.structuralTable = false
			content := c.renderSequence(childNodes(ch), capCtx)
