				parts = append(parts, strings.TrimSpace(content))
			}
		}
	}
	return strings.Join(parts, "\n\n")
}

func (c *converter) renderFallbackTable(n *html.Node, ctx rctx) string {
	sub := ctx
	sub.structuralTable = true
	sub.inTableCell = false
	return c.renderSequence(childNodes(n), sub)
}

func collectTableRows(table *html.Node) []*tableRow {
	var rows []*tableRow
	var process func(nodes []*html.Node, inThead bool)
	process = func(nodes []*html.Node, inThead bool) {
		for _, ch := range nodes {
			if ch.Type != html.ElementNode {
				continue
			}
			switch tagName(ch) {
			case "thead":
				process(childNodes(ch), true)
			case "tbody", "tfoot":
				process(childNodes(ch), false)
			case "tr":
				row := &tableRow{inThead: inThead}
				for _, cellNode := range childNodes(ch) {
					if cellNode.Type == html.ElementNode {
						tag := tagName(cellNode)
						if tag == "td" || tag == "th" {
							row.cells = append(row.cells, &tableCell{
								node:    cellNode,
								colspan: parseSpan(cellNode, "colspan"),
								rowspan: parseSpan(cellNode, "rowspan"),
							})
						}
					}
				}
				rows = append(rows, row)
			}
		}
	}
	process(childNodes(table), false)
	return rows
}

type pendingSpan struct {
	remaining int
	content   string
	origin    *html.Node
}

func expandTableGrid(display []*tableRow, cfg *config) ([][]string, [][]*html.Node) {
	_, _, spanBehavior := tableOpt(cfg)
	active := map[int]*pendingSpan{}
	var grid [][]string
	var origins [][]*html.Node
	for _, row := range display {
		slots := map[int]string{}
		orig := map[int]*html.Node{}
		col := 0
		placePending := func() {
			pend := active[col]
			if spanBehavior == "mirror" {
				slots[col] = pend.content
			} else {
				slots[col] = ""
			}
			orig[col] = pend.origin
			col++
		}
		for _, cell := range row.cells {
			// Fill any columns occupied by rowspans from above.
			for {
				if _, ok := active[col]; ok {
					placePending()
				} else {
					break
				}
			}
			startCol := col
			_ = startCol
			for k := 0; k < cell.colspan; k++ {
				if _, ok := active[col]; ok && k > 0 {
					placePending()
					k--
					continue
				}
				if k == 0 || spanBehavior == "mirror" {
					slots[col] = cell.content
				} else {
					slots[col] = ""
				}
				orig[col] = cell.node
				col++
			}
			// Register the rowspan for the columns this cell occupies.
			if cell.rowspan > 1 {
				// Determine the columns occupied by this cell.
				for cc := col - cell.colspan; cc < col; cc++ {
					if cc >= 0 {
						active[cc] = &pendingSpan{remaining: cell.rowspan, content: cell.content, origin: cell.node}
					}
				}
			}
		}
		// Place any remaining pending columns that are within reach.
		for {
			if _, ok := active[col]; ok {
				placePending()
			} else {
				break
			}
		}
		maxCol := -1
		for cc := range slots {
			if cc > maxCol {
				maxCol = cc
			}
		}
		rowSlots := make([]string, maxCol+1)
		rowOrigins := make([]*html.Node, maxCol+1)
		for cc := 0; cc <= maxCol; cc++ {
			if v, ok := slots[cc]; ok {
				rowSlots[cc] = v
				rowOrigins[cc] = orig[cc]
			}
		}
		grid = append(grid, rowSlots)
		origins = append(origins, rowOrigins)

		// Age the active spans: entries that were active during this
		// row lose one remaining row; freshly added entries start
		// counting from the next row.
		next := map[int]*pendingSpan{}
		for cc, pend := range active {
			if pend.remaining > 1 {
				next[cc] = &pendingSpan{remaining: pend.remaining - 1, content: pend.content, origin: pend.origin}
			}
		}
		active = next
	}
	return grid, origins
}

func convertCellNewlines(row []string) []string {
	out := make([]string, len(row))
	for i, cell := range row {
		out[i] = cellContentToBr(cell)
	}
	return out
}

// cellContentToBr replaces newlines with <br /> except for newlines
// that sit strictly inside a fenced code block.
func cellContentToBr(content string) string {
	if !strings.Contains(content, "\n") {
		return content
	}
	lines := strings.Split(content, "\n")
	var b strings.Builder
	inFence := false
	fenceLen := 0
	lineIsFence := make([]bool, len(lines))
	lineIsClosing := make([]bool, len(lines))
	for i, line := range lines {
		stripped := strings.TrimLeft(line, " \t")
		isF, run := fenceInfo(stripped)
		if !inFence {
			if isF {
				inFence = true
				fenceLen = run
				lineIsFence[i] = true
			}
		} else {
			if isF && run >= fenceLen && isFenceLine(stripped) {
				inFence = false
				lineIsFence[i] = true
				lineIsClosing[i] = true
			}
		}
	}
	_ = lineIsClosing
	inFence = false
	for i, line := range lines {
		if i > 0 {
			prevContent := inFence && !lineIsFence[i-1] && !lineIsFence[i]
			curContent := false
			// Recompute fence state before this line.
			curContent = prevContent && inFence
			_ = curContent
			if prevContent {
				b.WriteString("\n")
			} else {
				b.WriteString("<br />")
			}
		}
		b.WriteString(line)
		// Update fence state after writing the line.
		stripped := strings.TrimLeft(line, " \t")
		isF, run := fenceInfo(stripped)
		if !inFence {
			if isF {
				inFence = true
				fenceLen = run
			}
		} else {
			if isF && run >= fenceLen && isFenceLine(stripped) {
				inFence = false
			}
		}
	}
	return b.String()
}

func formatTable(header []string, body [][]string, aligns []string, cfg *config) string {
	padding, _, _ := tableOpt(cfg)
	numCols := len(header)
	if numCols == 0 {
		return ""
	}
	widths := make([]int, numCols)
	for col := 0; col < numCols; col++ {
		widths[col] = 1
	}
	measure := func(row []string) {
		for col := 0; col < numCols && col < len(row); col++ {
			if w := utf8.RuneCountInString(row[col]); w > widths[col] {
				widths[col] = w
			}
		}
	}
	measure(header)
	for _, row := range body {
		measure(row)
	}

	formatRow := func(row []string) string {
		cells := make([]string, numCols)
		for col := 0; col < numCols; col++ {
			content := ""
			if col < len(row) {
				content = row[col]
			}
			switch padding {
			case "aligned":
				pad := widths[col] - utf8.RuneCountInString(content)
				if pad < 0 {
					pad = 0
				}
				cells[col] = " " + content + strings.Repeat(" ", pad) + " "
			case "minimal":
				cells[col] = " " + content + " "
			default: // none
				cells[col] = content
			}
		}
		return "|" + strings.Join(cells, "|") + "|"
	}

	separator := func() string {
		cells := make([]string, numCols)
		for col := 0; col < numCols; col++ {
			var total int
			if padding == "aligned" {
				total = widths[col] + 2
				if total < 3 {
					total = 3
				}
			} else {
				total = 3
			}
			switch aligns[col] {
			case "left":
				cells[col] = ":" + strings.Repeat("-", total-1)
			case "center":
				cells[col] = ":" + strings.Repeat("-", total-2) + ":"
			case "right":
				cells[col] = strings.Repeat("-", total-1) + ":"
			default:
				cells[col] = strings.Repeat("-", total)
			}
		}
		return "|" + strings.Join(cells, "|") + "|"
	}

	var lines []string
	lines = append(lines, formatRow(header))
	lines = append(lines, separator())
	for _, row := range body {
		lines = append(lines, formatRow(row))
	}
	return strings.Join(lines, "\n")
}
