package main

import (
	"crypto/sha256"
	"errors"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

const globHint = "\n\nHere is how you can use a glob to match multiple files:\n\n    html2markdown --input \"src/*.html\" --output \"dist/\""

type fileTask struct {
	inputPath  string // empty means stdin
	outputDest string // empty means stdout
	isDirOut   bool
}

func execute(cfg *config, stdin io.Reader, stdout io.Writer) error {
	tasks, err := buildTasks(cfg)
	if err != nil {
		return err
	}
	conv := newConverter(cfg)
	for _, task := range tasks {
		if err := executeTask(cfg, conv, task, stdin, stdout); err != nil {
			return err
		}
	}
	return nil
}

func buildTasks(cfg *config) ([]fileTask, error) {
	if !cfg.inputSet {
		// Single task from stdin.
		task := fileTask{}
		if err := setTaskOutput(cfg, &task); err != nil {
			return nil, err
		}
		return []fileTask{task}, nil
	}

	matches, err := resolveInputFiles(cfg.input)
	if err != nil {
		return nil, err
	}
	if len(matches) == 0 {
		return nil, fmt.Errorf("no files found matching pattern %q%s", cfg.input, globHint)
	}
	if len(matches) == 1 {
		if info, statErr := os.Stat(matches[0]); statErr == nil && info.IsDir() {
			cleaned := filepath.Clean(matches[0])
			if cleaned != "." && cleaned != ".." {
				return nil, fmt.Errorf("input path %q is a directory, not a file%s", cfg.input, globHint)
			}
		}
		task := fileTask{inputPath: matches[0]}
		if err := setTaskOutput(cfg, &task); err != nil {
			return nil, err
		}
		return []fileTask{task}, nil
	}

	// Multiple input files need a directory output.
	if !cfg.outputSet {
		return nil, fmt.Errorf("when processing multiple input files --output needs to be a directory%s", globHint)
	}
	if !strings.HasSuffix(cfg.output, "/") {
		return nil, fmt.Errorf("when processing multiple input files, --output %q must end with %q to indicate a directory", cfg.output, cfg.output+"/")
	}
	tasks := make([]fileTask, 0, len(matches))
	for _, m := range matches {
		task := fileTask{inputPath: m}
		if err := setTaskOutput(cfg, &task); err != nil {
			return nil, err
		}
		tasks = append(tasks, task)
	}
	// De-duplicate output names.
	used := map[string]bool{}
	for i := range tasks {
		dest := tasks[i].outputDest
		if dest == "" {
			continue
		}
		if used[dest] {
			sum := sha256.Sum256([]byte(tasks[i].inputPath))
			hash := fmt.Sprintf("%x", sum)[:10]
			ext := filepath.Ext(dest)
			stem := strings.TrimSuffix(dest, ext)
			tasks[i].outputDest = stem + "." + hash + ext
		}
		used[tasks[i].outputDest] = true
	}
	return tasks, nil
}

func setTaskOutput(cfg *config, task *fileTask) error {
	if !cfg.outputSet {
		return nil
	}
	out := cfg.output
	if strings.HasSuffix(out, "/") {
		task.isDirOut = true
		name := "output"
		if task.inputPath != "" {
			base := filepath.Base(task.inputPath)
			ext := filepath.Ext(base)
			name = strings.TrimSuffix(base, ext)
		}
		task.outputDest = out + name + ".md"
		return nil
	}
	// Output is a file path.
	if info, err := os.Stat(out); err == nil && info.IsDir() {
		return fmt.Errorf("path %q exists and is a directory, did you mean %q?\n\nThe --output must end with \"/\" to indicate a directory", out, out+"/")
	}
	task.outputDest = out
	return nil
}

func executeTask(cfg *config, conv *converter, task fileTask, stdin io.Reader, stdout io.Writer) error {
	if task.outputDest != "" {
		dir := task.outputDest
		if !task.isDirOut {
			dir = filepath.Dir(task.outputDest)
		}
		if err := os.MkdirAll(dir, 0o755); err != nil {
			return err
		}
	}

	var content []byte
	var err error
	if task.inputPath == "" {
		content, err = io.ReadAll(stdin)
	} else {
		content, err = os.ReadFile(task.inputPath)
	}
	if err != nil {
		return err
	}

	markdown, err := conv.convert(content)
	if err != nil {
		return err
	}

	if task.outputDest == "" {
		_, err := fmt.Fprintln(stdout, markdown)
		return err
	}

	if !cfg.outputOverwrite {
		if _, err := os.Stat(task.outputDest); err == nil {
			return fmt.Errorf("output path %q already exists. Use --output-overwrite to replace existing files", cfg.output)
		} else if err != nil && !errors.Is(err, os.ErrNotExist) {
			return err
		}
	}
	return os.WriteFile(task.outputDest, []byte(markdown), 0o644)
}
