package main

import (
	"errors"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var errBadPattern = errors.New("syntax error in pattern")

func hasMeta(pattern string) bool {
	return strings.ContainsAny(pattern, "*?[{\\")
}

// resolveInputFiles expands the --input pattern following the
// behaviour of a doublestar-style glob that only returns files.
func resolveInputFiles(pattern string) ([]string, error) {
	if err := validateGlobPattern(pattern); err != nil {
		return nil, errBadPattern
	}
	if !hasMeta(pattern) {
		cleaned := filepath.Clean(pattern)
		if _, err := os.Lstat(cleaned); err != nil {
			return nil, nil
		}
		return []string{cleaned}, nil
	}

	absolute := filepath.IsAbs(pattern)
	var segments []string
	var fsRoot string
	var displayRoot string
	if absolute {
		fsRoot = "/"
		displayRoot = ""
		trimmed := strings.TrimPrefix(pattern, "/")
		segments = splitSegments(trimmed)
	} else {
		fsRoot = "."
		displayRoot = ""
		segments = splitSegments(pattern)
	}
	// Handle a leading "./" or "../" in relative patterns by keeping
	// it in the display prefix.
	matches := globMatch(fsRoot, displayRoot, segments, absolute)
	sortMatches(matches)
	return matches, nil
}

func splitSegments(pattern string) []string {
	if pattern == "" {
		return nil
	}
	return strings.Split(pattern, "/")
}

// sortMatches keeps duplicates (they matter for output naming) and
// orders matches like directory traversal does. Our matcher already
// yields entries in traversal order, so this is a no-op placeholder
// kept for clarity.
func sortMatches(matches []string) {}

// globMatch walks the filesystem matching pattern segments.
func globMatch(fsDir, display string, segments []string, absolute bool) []string {
	if len(segments) == 0 {
		return nil
	}
	seg := segments[0]
	last := len(segments) == 1

	joinDisplay := func(name string) string {
		if absolute {
			return display + "/" + name
		}
		if display == "" {
			return name
		}
		return display + "/" + name
	}
	joinFS := func(name string) string {
		if fsDir == "/" {
			return "/" + name
		}
		if fsDir == "." {
			return name
		}
		return fsDir + "/" + name
	}

	if seg == "**" {
		var out []string
		// ** matches zero segments.
		out = append(out, globMatch(fsDir, display, segments[1:], absolute)...)
		// ** matches one or more directory segments.
		entries := readDir(fsDir)
		for _, e := range entries {
			if isDirEntry(e) {
				out = append(out, globMatch(joinFS(e.Name()), joinDisplay(e.Name()), segments, absolute)...)
			}
		}
		return out
	}

	if seg == "." || seg == ".." {
		nd := joinFS(seg)
		disp := seg
		if absolute {
			disp = display + "/" + seg
		} else if display != "" {
			disp = display + "/" + seg
		}
		if last {
			if info, err := os.Stat(nd); err == nil && info.Mode().IsRegular() {
				return []string{filepath.Clean(disp)}
			}
			return nil
		}
		if info, err := os.Stat(nd); err == nil && info.IsDir() {
			return globMatch(nd, filepath.Clean(disp), segments[1:], absolute)
		}
		return nil
	}

	if !hasMeta(seg) {
		target := joinFS(seg)
		if last {
			if info, err := os.Lstat(target); err == nil && info.Mode().IsRegular() {
				return []string{joinDisplay(seg)}
			}
			return nil
		}
		if info, err := os.Stat(target); err == nil && info.IsDir() {
			return globMatch(target, joinDisplay(seg), segments[1:], absolute)
		}
		return nil
	}

	// Segment with meta characters.
	re, err := segmentRegex(seg)
	if err != nil {
		return nil
	}
	var out []string
	entries := readDir(fsDir)
	for _, e := range entries {
		if !re.MatchString(e.Name()) {
			continue
		}
		if last {
			if info, err := e.Info(); err == nil && info.Mode().IsRegular() {
				out = append(out, joinDisplay(e.Name()))
			}
			continue
		}
		if isDirEntry(e) {
			out = append(out, globMatch(joinFS(e.Name()), joinDisplay(e.Name()), segments[1:], absolute)...)
		}
	}
	return out
}

func readDir(dir string) []os.DirEntry {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil
	}
	// os.ReadDir already sorts by filename.
	return entries
}

func isDirEntry(e os.DirEntry) bool {
	if e.IsDir() {
		return true
	}
	// Do not follow symlinks for directories.
	return false
}

// segmentRegex converts a single path segment pattern to a regex.
func segmentRegex(seg string) (*regexp.Regexp, error) {
	var sb strings.Builder
	sb.WriteString("(?s)^")
	if err := writeSegmentRegex(&sb, seg); err != nil {
		return nil, err
	}
	sb.WriteString("$")
	return regexp.Compile(sb.String())
}

func writeSegmentRegex(sb *strings.Builder, seg string) error {
	i := 0
	for i < len(seg) {
		c := seg[i]
		switch c {
		case '*':
			sb.WriteString(".*")
			i++
		case '?':
			sb.WriteString(".")
			i++
		case '\\':
			if i+1 >= len(seg) {
				return errBadPattern
			}
			sb.WriteString(regexp.QuoteMeta(string(seg[i+1])))
			i += 2
		case '[':
			frag, consumed, err := parseCharClass(seg[i:])
			if err != nil {
				return err
			}
			sb.WriteString(frag)
			i += consumed
		case '{':
			alts, consumed, err := parseAlternates(seg[i:])
			if err != nil {
				return err
			}
			sb.WriteString("(?:")
			for j, alt := range alts {
				if j > 0 {
					sb.WriteString("|")
				}
				if err := writeSegmentRegex(sb, alt); err != nil {
					return err
				}
			}
			sb.WriteString(")")
			i += consumed
		default:
			sb.WriteString(regexp.QuoteMeta(string(c)))
			i++
		}
	}
	return nil
}

func parseCharClass(s string) (string, int, error) {
	// s starts with '['.
	i := 1
	negate := false
	if i < len(s) && (s[i] == '!' || s[i] == '^') {
		negate = true
		i++
	}
	var body strings.Builder
	first := true
	for {
		if i >= len(s) {
			return "", 0, errBadPattern
		}
		c := s[i]
		if c == ']' && !first {
			var sb strings.Builder
			sb.WriteString("[")
			if negate {
				sb.WriteString("^")
			}
			sb.WriteString(body.String())
			sb.WriteString("]")
			return sb.String(), i + 1, nil
		}
		first = false
		if c == '\\' {
			if i+1 >= len(s) {
				return "", 0, errBadPattern
			}
			body.WriteString(regexp.QuoteMeta(string(s[i+1])))
			i += 2
			continue
		}
		if c == '-' && body.Len() > 0 && i+1 < len(s) && s[i+1] != ']' {
			// Range: validate ordering.
			prev := body.String()
			prevRunes := []rune(prev)
			lo := prevRunes[len(prevRunes)-1]
			hi := rune(s[i+1])
			if lo > hi {
				return "", 0, errBadPattern
			}
			body.WriteString("-")
			i++
			continue
		}
		if c == '[' && i+1 < len(s) && s[i+1] == ':' {
			// POSIX character classes like [:alpha:] are not supported
			// specially; treat literally.
		}
		switch c {
		case '\\', ']', '^':
			body.WriteString("\\" + string(c))
		default:
			body.WriteString(string(c))
		}
		i++
	}
}

func parseAlternates(s string) ([]string, int, error) {
	// s starts with '{'.
	depth := 0
	var alts []string
	start := 1
	i := 0
	for i = 0; i < len(s); i++ {
		c := s[i]
		if c == '\\' {
			i++
			continue
		}
		if c == '{' {
			depth++
		} else if c == '}' {
			depth--
			if depth == 0 {
				alts = append(alts, s[start:i])
				return alts, i + 1, nil
			}
		} else if c == ',' && depth == 1 {
			alts = append(alts, s[start:i])
			start = i + 1
		}
	}
	return nil, 0, errBadPattern
}

func validateGlobPattern(pattern string) error {
	// Validate each segment.
	for _, seg := range strings.Split(pattern, "/") {
		if _, err := segmentRegex(seg); err != nil {
			return err
		}
		// segmentRegex treats a trailing backslash as an error and
		// unbalanced [ or { as errors.
	}
	// filepath.Match style validation for character classes spanning
	// segments is not needed.
	_ = sort.Strings
	return nil
}
