{"command":"cat > list.go <<'GO'
package main

import (
	"fmt"
	"strconv"
	"strings"

	"golang.org/x/net/html"
)

const listEndToken = "\x00LISTEND\x00"

// renderList renders a <ul> or <ol>.
func (c *converter) renderList(n *html.Node, ctx rctx) string {
	ordered := tagName(n) == "ol"

	type itemBuild struct {
		content   string
		lastBlock bool
		hasChunks bool
	}
	var items []*itemBuild
	var cur *itemBuild
	newItem := func() *itemBuild {
		it := &itemBuild{}
		items = append(items, it)
		cur = it
		return it
	}
	appendInline := func(it *itemBuild, raw string) {
		trimmed := strings.TrimSpace(raw)
		if trimmed == "" {
			return
		}
		if !it.hasChunks {
			it.content = trimmed
			it.hasChunks = true
			it.lastBlock = false
			return
		}
		if it.lastBlock {
			it.content += "\n\n" + trimmed
			it.lastBlock = false
			return
		}
		if len(raw) > 0 && isSpaceRune([]rune(raw)[0]) && !strings.HasSuffix(it.content, " ") {
			it.content += " "
		}
		it.content += trimmed
	}
	appendBlock := func(it *itemBuild, text string) {
		trimmed := strings.TrimSpace(text)
		if trimmed == "" {
			return
		}
		if !it.hasChunks {
			it.content = trimmed
			it.hasChunks = true
			it.lastBlock = true
			return
		}
		it.content += "\n\n" + trimmed
		it.lastBlock = true
	}

	ib := &inlineBuilder{state: lineBlockStart}
	flushInline := func() {
		raw := ib.buf
		ib = &inlineBuilder{state: lineBlockStart}
		if strings.TrimSpace(raw) == "" {
			return
		}
		if cur == nil {
			newItem()
		}
		appendInline(cur, raw)
	}

	for _, ch := range childNodes(n) {
		if ch.Type == html.ElementNode && tagName(ch) == "li" {
			flushInline()
			it := newItem()
			content := c.renderSequence(childNodes(ch), ctx)
			if strings.TrimSpace(content) != "" {
				it.content = strings.TrimSpace(content)
				it.hasChunks = true
				it.lastBlock = false
			}
			continue
		}
		if isBlockNode(ch, ctx) {
			flushInline()
			if cur == nil {
				newItem()
			}
			appendBlock(cur, c.renderNode(ch, ctx))
			continue
		}
		c.renderInline(ch, ib, ctx)
	}
	flushInline()

	var contents []string
	for _, it := range items {
		if strings.TrimSpace(it.content) != "" {
			contents = append(contents, strings.TrimSpace(it.content))
		}
	}
	if len(contents) == 0 {
		return ""
	}

	start := 1
	if ordered {
		if v, ok := getAttr(n, "start"); ok {
			if num, err := strconv.Atoi(v); err == nil {
				start = num
			}
		}
	}

	markers := make([]string, len(contents))
	if ordered {
		width := len(strconv.Itoa(start + len(contents) - 1))
		for i := range contents {
			markers[i] = fmt.Sprintf("%0*d.", width, start+i)
		}
	} else {
		for i := range contents {
			markers[i] = "-"
		}
	}
	indentWidth := 0
	for _, m := range markers {
		if len(m)+1 > indentWidth {
			indentWidth = len(m) + 1
		}
	}
	indent := strings.Repeat(" ", indentWidth)

	var lines []string
	for i, content := range contents {
		for j, line := range strings.Split(content, "\n") {
			if j == 0 {
				lines = append(lines, markers[i]+" "+line)
			} else {
				lines = append(lines, indent+line)
			}
		}
	}
	return strings.Join(lines, "\n") + "\n\n" + listEndToken
}

// processListEndTokens replaces list-end tokens with the marker text
// when the next block is also a list, and removes them otherwise.
func processListEndTokens(text string) string {
	if !strings.Contains(text, listEndToken) {
		return text
	}
	lines := strings.Split(text, "\n")
	var out []string
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if !isTokenLine(line) {
			out = append(out, line)
			continue
		}
		// Find the next non-blank line.
		next := ""
		for j := i + 1; j < len(lines); j++ {
			if !isBlankLine(lines[j]) {
				next = lines[j]
				break
			}
		}
		keep := false
		if next != "" && !isTokenLine(next) && isListItemLine(next) && lineIndent(next) == lineIndent(line) {
			keep = true
		}
		if keep {
			out = append(out, strings.Replace(line, listEndToken, "<!--THE END-->", 1))
		} else {
			// Drop one adjacent blank line.
			if len(out) > 0 && isBlankLine(out[len(out)-1]) {
				out = out[:len(out)-1]
			}
		}
	}
	result := strings.Join(out, "\n")
	// Remove any leftover tokens (e.g. embedded in other content).
	result = strings.ReplaceAll(result, listEndToken, "")
	return result
}

func stripQuotePrefixes(line string) string {
	s := strings.TrimLeft(line, " \t")
	for strings.HasPrefix(s, ">") {
		s = s[1:]
		s = strings.TrimLeft(s, " ")
		if !strings.HasPrefix(s, ">") {
			break
		}
		s = strings.TrimLeft(s, " \t")
	}
	return s
}

func isTokenLine(line string) bool {
	return stripQuotePrefixes(line) == listEndToken || strings.TrimSpace(stripQuotePrefixes(line)) == listEndToken
}

func isBlankLine(line string) bool {
	return strings.TrimSpace(stripQuotePrefixes(line)) == ""
}

func lineIndent(line string) int {
	s := line
	// Remove blockquote prefixes.
	for {
		t := strings.TrimLeft(s, " \t")
		// Calculate spaces removed so far by counting later.
		s = t
		if strings.HasPrefix(s, ">") {
			s = s[1:]
			if strings.HasPrefix(s, " ") {
				s = s[1:]
			}
			continue
		}
		break
	}
	n := 0
	for n < len(s) && s[n] == ' ' {
		n++
	}
	return n
}

func isListItemLine(line string) bool {
	s := stripQuotePrefixes(line)
	s = strings.TrimLeft(s, " \t")
	if strings.HasPrefix(s, "- ") || s == "-" {
		return true
	}
	// Ordered list: digits '.' space or end.
	i := 0
	for i < len(s) && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	if i > 0 && i < len(s) && s[i] == '.' {
		if i+1 >= len(s) || s[i+1] == ' ' {
			return true
		}
	}
	return false
}
GO
gofmt -w list.go 2>&1 | head"}

