// ---------- escaping lookahead ----------

var escapeScopeBoundaryTags = map[string]bool{
	"td": true, "th": true, "caption": true, "body": true, "html": true,
}

func isEscapeScopeBoundary(n *html.Node) bool {
	if n.Type != html.ElementNode {
		return false
	}
	if blockTags[tagName(n)] {
		return true
	}
	return escapeScopeBoundaryTags[tagName(n)]
}

// scopeAncestorOf finds the boundary element that limits the inline
// scope of the given node.
func scopeAncestorOf(n *html.Node) *html.Node {
	cur := n
	for cur.Parent != nil {
		if isEscapeScopeBoundary(cur) {
			return cur
		}
		cur = cur.Parent
	}
	return cur
}

// nextRuneInScope finds the next rendered character after the given
// node within its inline scope.
func (c *converter) nextRuneInScope(n *html.Node, ctx rctx) (rune, bool) {
	scope := scopeAncestorOf(n)
	cur := n
	for cur != scope {
		if cur.NextSibling != nil {
			next := cur.NextSibling
			for next != nil {
				if r, ok := c.firstRenderedRune(next, ctx); ok {
					return r, true
				}
				next = next.NextSibling
			}
			return 0, false
		}
		if cur.Parent == nil {
			return 0, false
		}
		cur = cur.Parent
	}
	return 0, false
}

// hasClosingBracketLater reports whether a ']' character appears in
// any text node after the given node within its inline scope.
func (c *converter) hasClosingBracketLater(n *html.Node, ctx rctx) bool {
	scope := scopeAncestorOf(n)
	found := false
	var walk func(node *html.Node, after bool) bool
	// Walk the scope subtree in document order, starting after n.
	var collect func(node *html.Node, inside *bool)
	_ = walk
	_ = collect
	// Simpler: iterate all text nodes in scope; once we pass n, check.
	passed := false
	var scan func(node *html.Node)
	scan = func(node *html.Node) {
		if found {
			return
		}
		if node == n {
			passed = true
		} else if passed && node.Type == html.TextNode {
			if indexByteStr(node.Data, ']') {
				found = true
				return
			}
		}
		for ch := node.FirstChild; ch != nil; ch = ch.NextSibling {
			scan(ch)
			if found {
				return
			}
		}
	}
