	if ignoredTags[tag] {
		return 0, false
	}
	switch tag {
	case "br":
		return '\n', true
	case "img":
		if src, ok := getAttr(n, "src"); !ok || strings.TrimSpace(src) == "" {
			return 0, false
		}
		return '!', true
	case "wbr", "area", "embed", "param", "track":
		return 0, false
	case "code", "kbd", "samp", "tt", "var":
		if codeText(n) == "" && tag == "code" {
