func processListEndTokens(text string) string {
	if !strings.Contains(text, "\\x00LISTEND") {
		return text
	}
	lines := strings.Split(text, "\\n")
	var out []string
	for i := 0; i < len(lines); i++ {
		line := lines[i]
		if !isTokenLine(line) {
			out = append(out, line)
			continue
		}
		if strings.Contains(line, "\\x00LISTENDK\\x00") {
			out = append(out, strings.Replace(line, "\\x00LISTENDK\\x00", "<!--THE END-->", 1))
		} else {
			// Drop one adjacent blank line.
			if len(out) > 0 && isBlankLine(out[len(out)-1]) {
				out = out[:len(out)-1]
			}
		}
