// nextBlockStartsWithList determines whether the block following the
// given list (at the list's own sequence level) is a list or a
// container whose first block content is a list.
func (c *converter) nextBlockStartsWithList(list *html.Node) bool {
	cur := list
	for {
		sib := cur.NextSibling
		for sib != nil {
			switch c.startsWithListKind(sib) {
			case startList:
				return true
			case startOther:
				return false
			}
			sib = sib.NextSibling
		}
		// All following siblings were neutral.
		if cur.Parent == nil {
			return false
		}
		cur = cur.Parent
		if cur.Type == html.ElementNode && tagName(cur) == "li" {
			// The block after this list is the next item of the
			// enclosing list, not a new list block.
			return false
		}
	}
}

type startKind int

const (
	startNeutral startKind = iota
	startList
	startOther
)

// startsWithListKind classifies the first rendered content of a node.
func (c *converter) startsWithListKind(n *html.Node) startKind {
	switch n.Type {
	case html.TextNode:
		if strings.TrimSpace(n.Data) == "" {
			return startNeutral
		}
		return startOther
	case html.ElementNode:
		// handled below
	default:
		return startNeutral
	}
	tag := tagName(n)
	if ignoredTags[tag] {
		return startNeutral
	}
	switch tag {
	case "ul", "ol":
		return startList
	case "br", "wbr", "area", "embed", "param", "track", "link", "meta":
		return startNeutral
	case "img":
		return startOther
	case "li":
		return startOther
	case "pre":
		return startOther
	}
	// Look at children in order.
	for _, ch := range childNodes(n) {
		switch c.startsWithListKind(ch) {
		case startList:
			return startList
		case startOther:
			return startOther
		}
	}
	// A block container with no significant content first is neutral
	// when empty; an image with valid src handled above.
	if blockTags[tag] && !hasRenderableContent(n) {
		return startNeutral
	}
	if tag == "hr" {
		return startOther
	}
	// Inline elements with content are "other"; without content they
	// are neutral.
	if hasRenderableContent(n) {
		return startOther
	}
	return startNeutral
}

func hasRenderableContent(n *html.Node) bool {
	if n.Type == html.TextNode {
		return strings.TrimSpace(n.Data) != ""
	}
	if n.Type != html.ElementNode {
		return false
	}
	if tagName(n) == "img" {
		src, ok := getAttr(n, "src")
		return ok && strings.TrimSpace(src) != ""
	}
	for _, ch := range childNodes(n) {
		if hasRenderableContent(ch) {
			return true
		}
	}
	return false
}

