new_region = '''type inlineBuilder struct {
	buf          []byte
	state        lineState
	barrier      bool
	afterBlock   bool
	swallowSpace bool
	rawBr        bool
}

func (b *inlineBuilder) str() string { return string(b.buf) }

func hasContent(s string) bool {
	return strings.Trim(s, " \\t\\n\\r") != ""
}

func (b *inlineBuilder) ensureBlockSep(s string) {
	if !b.afterBlock {
		return
	}
	if !hasContent(s) {
		return
	}
	b.afterBlock = false
	if len(bytes.TrimSpace(b.buf)) == 0 {
		return
	}
	if !bytes.HasSuffix(b.buf, []byte("\\n\\n")) {
		if bytes.HasSuffix(b.buf, []byte("\\n")) {
			b.buf = append(b.buf, '\\n')
		} else {
			b.buf = append(b.buf, "\\n\\n"...)
		}
	}
}

func (b *inlineBuilder) noteWritten(s string) {
	if idx := strings.LastIndex(s, "\\n"); idx >= 0 {
		rest := s[idx+1:]
		if !hasContent(rest) {
			b.state = lineAfterBreak
		} else {
			b.state = lineNone
		}
		return
	}
	if hasContent(s) {
		b.state = lineNone
	}
}

func (b *inlineBuilder) Text(s string) {
	if s == "" {
		return
	}
	b.ensureBlockSep(s)
	if b.swallowSpace {
		b.swallowSpace = false
		if strings.HasPrefix(s, " ") {
			s = s[1:]
			if s == "" {
				return
			}
		}
	}
	// At the start of a line, a leading space is dropped.
	if (b.state == lineBlockStart || b.state == lineAfterBreak) && strings.HasPrefix(s, " ") && bytes.IndexByte(b.buf, '\\n') >= 0 && lineStartOnlySpaces(b.buf) {
		s = s[1:]
		if s == "" {
			return
		}
	}
	if !b.barrier && bytes.HasSuffix(b.buf, []byte(" ")) && strings.HasPrefix(s, " ") {
		s = s[1:]
		if s == "" {
			return
		}
	}
	b.buf = append(b.buf, s...)
	b.noteWritten(s)
	b.barrier = false
}

// lineStartOnlySpaces reports whether the text written so far on the
// current line consists only of ASCII spaces (or is empty).
func lineStartOnlySpaces(buf []byte) bool {
	idx := bytes.LastIndex(buf, []byte("\\n"))
	rest := buf
	if idx >= 0 {
		rest = buf[idx+1:]
	}
	for i := 0; i < len(rest); i++ {
		if rest[i] != ' ' {
			return false
		}
	}
	return true
}

func (b *inlineBuilder) Raw(s string) {
	if s == "" {
		return
	}
	b.swallowSpace = false
	b.ensureBlockSep(s)
	b.buf = append(b.buf, s...)
	b.noteWritten(s)
	b.barrier = false
}

func (b *inlineBuilder) Barrier() {
	b.barrier = true
}

func (b *inlineBuilder) WriteBlockChunk(chunk string, tags ...string) {
	if strings.TrimSpace(chunk) == "" {
		return
	}
	if len(bytes.TrimSpace(b.buf)) != 0 {
		b.buf = bytes.TrimRight(b.buf, " \\t")
		for bytes.HasSuffix(b.buf, []byte(" \\n")) || bytes.HasSuffix(b.buf, []byte("\\t\\n")) {
			b.buf = append(b.buf[:len(b.buf)-2], '\\n')
		}
